ын нотолгоог холбон судална.","topicIds":["1.1","1.2","1.3","1.4"]},{"id":"2","num":"2","title":"Химийн урвал","pages":"42–74","summary":"Ойлголт, тооцоо, туршилтын нотолгоог холбон судална.","topicIds":["2.1","2.2","2.3"]},{"id":"3","num":"3","title":"Органик биш бодис. Шинж чанар","pages":"75–100","summary":"Ойлголт, тооцоо, туршилтын нотолгоог холбон судална.","topicIds":["3.1","3.2","3.3"]},{"id":"4","num":"4","title":"Органик бодис. Шинж чанар","pages":"101–146","summary":"Ойлголт, тооцоо, туршилтын нотолгоог холбон судална.","topicIds":["4.1","4.2","4.3","4.4","4.5","4.6"]}],"topics":[{"id":"1.1","chapterId":"1","title":"Бодисын тоо хэмжээ ба стехиометр","bookPages":"6–15","objectives":[{"id":"g10-1.1-o1","text":"0.20 моль/л NaCl-ийн 250 мл уусмалд хэдэн грамм давс хэрэгтэй вэ?"},{"id":"g10-1.1-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Моль"],"notes":[{"id":"g10-1.1-n1","title":"Бодисын тоо хэмжээ ба стехиометр","blocks":[{"t":"key","term":"Моль","x":"6.022×10²³ жижиг хэсэг агуулсан бодисын тоо хэмжээний нэгж."},{"t":"p","x":"Массаас молийг n=m/M, уусмалаас n=cV гэж олно. V-ийг литрт шилжүүлж, тэнцүүлсэн урвалын коэффициентээр харьцуулна."},{"t":"p","x":"Хязгаарлагч эх бодис бүтээгдэхүүний дээд хэмжээг тогтооно. Хийн эзлэхүүнд температур, даралтыг заавал өгнө; 25°C, 100 кПа-д идеал молийн эзлэхүүн ойролцоогоор 24.8 л/моль."},{"t":"ex","q":"0.20 моль/л NaCl-ийн 250 мл уусмалд хэдэн грамм давс хэрэгтэй вэ?","a":"n=0.20×0.250=0.050 моль; m=0.050×58.44=2.922 г."}]},{"id":"g10-1.1-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Уусмалыг шингэрүүлэхэд ууссан бодисын моль хадгалагдана; эцсийн эзлэхүүн нь нэмсэн усны эзлэхүүнтэй заавал тэнцэхгүй."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Массыг молийн массаар хуваахад ямар нэгж гарах вэ?","a":"моль — Массаас молийг n=m/M, уусмалаас n=cV гэж олно. V-ийг литрт шилжүүлж, тэнцүүлсэн урвалын коэффициентээр харьцуулна."}]}],"flashcards":[{"id":"g10-1.1-c1","front":"Моль гэж юу вэ?","back":"6.022×10²³ жижиг хэсэг агуулсан бодисын тоо хэмжээний нэгж."},{"id":"g10-1.1-c2","front":"0.20 моль/л NaCl-ийн 250 мл уусмалд хэдэн грамм давс хэрэгтэй вэ?","back":"n=0.20×0.250=0.050 моль; m=0.050×58.44=2.922 г."},{"id":"g10-1.1-c3","front":"Массыг молийн массаар хуваахад ямар нэгж гарах вэ?","back":"моль"},{"id":"g10-1.1-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Уусмалыг шингэрүүлэхэд ууссан бодисын моль хадгалагдана; эцсийн эзлэхүүн нь нэмсэн усны эзлэхүүнтэй заавал тэнцэхгүй."}],"quiz":[{"id":"g10-1.1-q1","question":"Массыг молийн массаар хуваахад ямар нэгж гарах вэ?","options":["моль","г/моль","л","моль/л"],"answer":0,"explanation":"Массаас молийг n=m/M, уусмалаас n=cV гэж олно. V-ийг литрт шилжүүлж, тэнцүүлсэн урвалын коэффициентээр харьцуулна. Хязгаарлагч эх бодис бүтээгдэхүүний дээд хэмжээг тогтооно. Хийн эзлэхүүнд температур, даралтыг заавал өгнө; 25°C, 100 кПа-д идеал молийн эзлэхүүн ойролцоогоор 24.8 л/моль."},{"id":"g10-1.1-q2","question":"0.5 моль NaCl-д хэдэн томьёоны нэгж байх вэ?","options":["3.011×10²³","6.022×10²³","0.5","1.2044×10²⁴"],"answer":0,"explanation":"N=nNₐ=0.5×6.022×10²³. Ионы нэгдлийг молекул гэж нэрлэхгүй."}],"questions":[{"id":"g10-1.1-s1","level":"medium","stem":"0.20 моль/л NaCl-ийн 250 мл уусмалд хэдэн грамм давс хэрэгтэй вэ?","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["n=0.20×0.250=0.050 моль; m=0.050×58.44=2.922 г.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"n=0.20×0.250=0.050 моль; m=0.050×58.44=2.922 г."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Уусмалыг шингэрүүлэхэд ууссан бодисын моль хадгалагдана; эцсийн эзлэхүүн нь нэмсэн усны эзлэхүүнтэй заавал тэнцэхгүй."],"model":"Уусмалыг шингэрүүлэхэд ууссан бодисын моль хадгалагдана; эцсийн эзлэхүүн нь нэмсэн усны эзлэхүүнтэй заавал тэнцэхгүй."}]}],"practicals":[{"id":"g10-mole-prac","title":"Масс, моль ба жижиг хэсэг","ref":"Хими X · х.7–9","aim":"Масс, моль ба жижиг хэсэг — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Тавцанд нэг бодисын хэмжсэн дээж хий.","Жинг ажиллуулж масс, молийн тоо ба жижиг хэсгийн тоог унш.","Массыг өөрчилж эсвэл өөр бодисын шинэ дээж авч харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. n=m/M, N=nNₐ; Nₐ=6.02214076×10²³ моль⁻¹.","labActivityId":"g10-mole"},{"id":"g10-solution-prac","title":"Тодорхой концентрацтай уусмал бэлтгэх","ref":"Хими X · х.13–15","aim":"Тодорхой концентрацтай уусмал бэлтгэх — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Хэмжүүрт колбонд NaCl-ийн тооцоолсон массыг хий.","Усыг хэсэгчлэн нэмж, колбоны эцсийн эзлэхүүнийг хэмж.","Багажийг ажиллуулж талст уусах ба концентрацыг тэмдэглэ; шингэрүүлж шинэ нөхцөлтэй харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. m=cVM; V нь литр. Хэмжүүрт колбо, жин, юүлүүр, угаагуур шаардлагатай.","labActivityId":"g10-solution"}]},{"id":"1.2","chapterId":"1","title":"Бодисын цэвэршлийг үнэлэх арга","bookPages":"16–24","objectives":[{"id":"g10-1.2-o1","text":"Толбо 3.0 см, уусгагчийн фронт 5.0 см явбал Rf хэд вэ?"},{"id":"g10-1.2-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Хроматограмм"],"notes":[{"id":"g10-1.2-n1","title":"Бодисын цэвэршлийг үнэлэх арга","blocks":[{"t":"key","term":"Хроматограмм","x":"Холимгийн бүрэлдэхүүний ялгаатай шилжилтийг харуулсан зураг."},{"t":"p","x":"Цэвэр бодис тогтмол даралтад нарийн мужид хайлна. Бохирдол хайлах цэгийг бууруулж, мужийг өргөсгөж болно. Буцлах цэгийг харьцуулахдаа даралт ижил байна."},{"t":"p","x":"Цаасан хроматографид уусгагч дээш зөөгдөхөд бүрэлдэхүүнүүд цаастай харилцан үйлчлэх ба уусах чадвараасаа шалтгаалан ялгарна. Эхлэх шугам уусгагчаас дээр байна."},{"t":"ex","q":"Толбо 3.0 см, уусгагчийн фронт 5.0 см явбал Rf хэд вэ?","a":"Rf=3.0/5.0=0.60; нэгжгүй, ижил уусгагч ба нөхцөлд харьцуулна."}]},{"id":"g10-1.2-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Нэг толбо харагдах нь бүх нөхцөлд цэвэр бодис болохыг батлахгүй; хоёр бүрэлдэхүүн давхцаж болно."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Rf-ийн зөв илэрхийлэл аль вэ?","a":"Толбо/фронт — Цэвэр бодис тогтмол даралтад нарийн мужид хайлна. Бохирдол хайлах цэгийг бууруулж, мужийг өргөсгөж болно. Буцлах цэгийг харьцуулахдаа даралт ижил байна."}]}],"flashcards":[{"id":"g10-1.2-c1","front":"Хроматограмм гэж юу вэ?","back":"Холимгийн бүрэлдэхүүний ялгаатай шилжилтийг харуулсан зураг."},{"id":"g10-1.2-c2","front":"Толбо 3.0 см, уусгагчийн фронт 5.0 см явбал Rf хэд вэ?","back":"Rf=3.0/5.0=0.60; нэгжгүй, ижил уусгагч ба нөхцөлд харьцуулна."},{"id":"g10-1.2-c3","front":"Rf-ийн зөв илэрхийлэл аль вэ?","back":"Толбо/фронт"},{"id":"g10-1.2-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Нэг толбо харагдах нь бүх нөхцөлд цэвэр бодис болохыг батлахгүй; хоёр бүрэлдэхүүн давхцаж болно."}],"quiz":[{"id":"g10-1.2-q1","question":"Rf-ийн зөв илэрхийлэл аль вэ?","options":["Фронт/толбо","Толбо/фронт","Толбо×фронт","Фронт−толбо"],"answer":1,"explanation":"Цэвэр бодис тогтмол даралтад нарийн мужид хайлна. Бохирдол хайлах цэгийг бууруулж, мужийг өргөсгөж болно. Буцлах цэгийг харьцуулахдаа даралт ижил байна. Цаасан хроматографид уусгагч дээш зөөгдөхөд бүрэлдэхүүнүүд цаастай харилцан үйлчлэх ба уусах чадвараасаа шалтгаалан ялгарна. Эхлэх шугам уусгагчаас дээр байна."},{"id":"g10-1.2-q2","question":"Эхлэх толбо уусгагчийн түвшнээс хаана байх ёстой вэ?","options":["Дээр","Доор","Заавал яг түвшинд","Байрлал хамаагүй"],"answer":0,"explanation":"Толбо усанд живбэл дээж камерын уусгагчид угаагдаж хроматограмм алдагдана."}],"questions":[{"id":"g10-1.2-s1","level":"medium","stem":"Толбо 3.0 см, уусгагчийн фронт 5.0 см явбал Rf хэд вэ?","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["Rf=3.0/5.0=0.60; нэгжгүй, ижил уусгагч ба нөхцөлд харьцуулна.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"Rf=3.0/5.0=0.60; нэгжгүй, ижил уусгагч ба нөхцөлд харьцуулна."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Нэг толбо харагдах нь бүх нөхцөлд цэвэр бодис болохыг батлахгүй; хоёр бүрэлдэхүүн давхцаж болно."],"model":"Нэг толбо харагдах нь бүх нөхцөлд цэвэр бодис болохыг батлахгүй; хоёр бүрэлдэхүүн давхцаж болно."}]}],"practicals":[{"id":"g10-melting-prac","title":"Бензойны хүчлийн хайлах муж","ref":"Хими X · х.17","aim":"Бензойны хүчлийн хайлах муж — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т цэвэр бензойны хүчил, ②-т ижил хүчил ба бага элс бэлтгэ.","Термостатыг 125°C хүртэл өсгөж халаалт, багажийг асаа.","Хатуу ба хайлсан хэсгийн хэмжээг харьцуулж хайлах мужийг тэмдэглэ."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Цэвэр дээж ойролцоогоор 122.4°C; бохирдолтой дээжийн 118–121°C нь номын жишээ муж.","labActivityId":"g10-melting"},{"id":"g10-boiling-prac","title":"Ацетоны буцлах цэг ба усан банн","ref":"Хими X · х.18","aim":"Ацетоны буцлах цэг ба усан банн — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т 5 мл ацетон, ③-т банны ус хий.","Банны температурыг 70°C болгож халаалт ба багажийг ажиллуул.","Буцлах үеийн температур, үлдсэн шингэн ба ②-т цугласан конденсатыг хэмж."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Ацетон 1 атм-д ойролцоогоор 56°C-д буцална. Даралтын хамаарал нь ойролцоо загвар.","labActivityId":"g10-boiling"},{"id":"g10-chromatography-prac","title":"Бэхний цаасан хроматограф","ref":"Хими X · х.21–22","aim":"Бэхний цаасан хроматограф — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Камерын ① үүрэнд 60 мл-ээс бага ус хий; ③-т цаас байрлуул.","②-т нэг бэхний дээж нэмээд ажиллуул; фронт ба толбоны зайг хэмж.","Шинэ угсралтад өөр бэхээр давтаж Rf-ийг харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"Толбо/фронт=Rf; уусгагчийн түвшин эхлэх толбоноос доор байна.","labActivityId":"g10-chromatography"}]},{"id":"1.3","chapterId":"1","title":"Давс гаргаж авах, цэвэрлэх арга","bookPages":"25–33","objectives":[{"id":"g10-1.3-o1","text":"25.0 мл 0.10 М HCl-ийг 0.10 М NaOH-оор саармагжуулахад хэдэн мл хэрэгтэй вэ?"},{"id":"g10-1.3-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Титрлэлт"],"notes":[{"id":"g10-1.3-n1","title":"Давс гаргаж авах, цэвэрлэх арга","blocks":[{"t":"key","term":"Титрлэлт","x":"Мэдэгдсэн концентрацтай уусмалаар урвалд оруулж үл мэдэгдэх тоо хэмжээг тогтоох арга."},{"t":"p","x":"Уусдаг давсыг хүчил ба уусдаггүй оксидоор гаргахдаа оксидыг илүүдлээр авч, үлдэгдлийг шүүж, шүүгдсийг өтгөрүүлээд хөргөн талстжуулна."},{"t":"p","x":"Уусдаг хүчил, суурийн хольцод илүүдэл бодисыг шүүх боломжгүй. Титрлэлтээр харьцааг олж, индикаторгүй давтан бэлтгэнэ. Уусдаггүй давсыг тунадасжуулж шүүж, угааж, хатаана."},{"t":"ex","q":"25.0 мл 0.10 М HCl-ийг 0.10 М NaOH-оор саармагжуулахад хэдэн мл хэрэгтэй вэ?","a":"HCl + NaOH → NaCl + H₂O. 1:1 тул 25.0 мл NaOH."}]},{"id":"g10-1.3-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Гарц = бодитоор авсан хуурай бүтээгдэхүүний масс / онолын масс ×100%. Нойтон талстыг жинлэх нь гарцыг хуурамчаар өсгөнө."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"CuO-гийн илүүдлийг ямар аргаар салгах вэ?","a":"Шүүх — Уусдаг давсыг хүчил ба уусдаггүй оксидоор гаргахдаа оксидыг илүүдлээр авч, үлдэгдлийг шүүж, шүүгдсийг өтгөрүүлээд хөргөн талстжуулна."}]}],"flashcards":[{"id":"g10-1.3-c1","front":"Титрлэлт гэж юу вэ?","back":"Мэдэгдсэн концентрацтай уусмалаар урвалд оруулж үл мэдэгдэх тоо хэмжээг тогтоох арга."},{"id":"g10-1.3-c2","front":"25.0 мл 0.10 М HCl-ийг 0.10 М NaOH-оор саармагжуулахад хэдэн мл хэрэгтэй вэ?","back":"HCl + NaOH → NaCl + H₂O. 1:1 тул 25.0 мл NaOH."},{"id":"g10-1.3-c3","front":"CuO-гийн илүүдлийг ямар аргаар салгах вэ?","back":"Шүүх"},{"id":"g10-1.3-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Гарц = бодитоор авсан хуурай бүтээгдэхүүний масс / онолын масс ×100%. Нойтон талстыг жинлэх нь гарцыг хуурамчаар өсгөнө."}],"quiz":[{"id":"g10-1.3-q1","question":"CuO-гийн илүүдлийг ямар аргаар салгах вэ?","options":["Нэрэх","Титрлэх","Шүүх","Хроматограф"],"answer":2,"explanation":"Уусдаг давсыг хүчил ба уусдаггүй оксидоор гаргахдаа оксидыг илүүдлээр авч, үлдэгдлийг шүүж, шүүгдсийг өтгөрүүлээд хөргөн талстжуулна. Уусдаг хүчил, суурийн хольцод илүүдэл бодисыг шүүх боломжгүй. Титрлэлтээр харьцааг олж, индикаторгүй давтан бэлтгэнэ. Уусдаггүй давсыг тунадасжуулж шүүж, угааж, хатаана."},{"id":"g10-1.3-q2","question":"Талстын бодит масс 4 г, онолын масс 5 г бол гарц хэд вэ?","options":["125%","20%","80%","100%"],"answer":2,"explanation":"4/5×100=80%. Хуурай бүтээгдэхүүний массыг хэрэглэнэ."}],"questions":[{"id":"g10-1.3-s1","level":"medium","stem":"25.0 мл 0.10 М HCl-ийг 0.10 М NaOH-оор саармагжуулахад хэдэн мл хэрэгтэй вэ?","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["HCl + NaOH → NaCl + H₂O. 1:1 тул 25.0 мл NaOH.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"HCl + NaOH → NaCl + H₂O. 1:1 тул 25.0 мл NaOH."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Гарц = бодитоор авсан хуурай бүтээгдэхүүний масс / онолын масс ×100%. Нойтон талстыг жинлэх нь гарцыг хуурамчаар өсгөнө."],"model":"Гарц = бодитоор авсан хуурай бүтээгдэхүүний масс / онолын масс ×100%. Нойтон талстыг жинлэх нь гарцыг хуурамчаар өсгөнө."}]}],"practicals":[{"id":"g10-salt-oxide-prac","title":"CuO-оос зэсийн сульфат гаргах","ref":"Хими X · х.25–30","aim":"CuO-оос зэсийн сульфат гаргах — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Савандаа хүчил авч CuO-г хэсэгчлэн нэмж хутга.","Илүүдэл хатуу CuO-г шүүж салга.","Шүүгдсийг өтгөрүүлэх ба хөргөж талстжуулах дарааллыг тэмдэглэ."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"CuO + H₂SO₄ → CuSO₄ + H₂O. Илүүдэл оксидыг шүүх нь ууссан давсыг салгахгүй.","labActivityId":"g10-salt-oxide"},{"id":"g10-titration-prac","title":"Титрлэлтээр NaCl гаргах","ref":"Хими X · х.26–27","aim":"Титрлэлтээр NaCl гаргах — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Бюреткийн эхний заалт ба колбонд авсан хүчлийн эзлэхүүнийг бич.","Индикатор нэмж суурийг хэсэгчлэн өг; өнгө өөрчлөгдөх цэгийг тэмдэглэ.","Давтан титрлэлтийн зарцуулалтыг харьцуул; давс авахдаа индикаторгүй давтахыг тайлбарла."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"HCl + NaOH → NaCl + H₂O. Зарцуулалт=эцсийн−эхний заалт.","labActivityId":"g10-titration"},{"id":"g10-precipitation-prac","title":"Уусдаггүй давсыг тунадасжуулж цэвэрлэх","ref":"Хими X · х.28–30","aim":"Уусдаггүй давсыг тунадасжуулж цэвэрлэх — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["AgNO₃ ба NaCl-ийн тусдаа дээж бэлтгэ.","Хэсэгчилж хольж цагаан тунадас үүсэхийг ажигла.","Тунадасыг шүүх, усаар угаах ба хатаах зорилгыг ялгаж бич."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"Ag⁺ + Cl⁻ → AgCl↓. Угаах нь уусдаг бохирдлыг зайлуулна.","labActivityId":"g10-precipitation"}]},{"id":"1.4","chapterId":"1","title":"Ион ба хийг таних арга","bookPages":"34–40","objectives":[{"id":"g10-1.4-o1","text":"Шохойн ус булингартах урвалыг бич."},{"id":"g10-1.4-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Чанарын сорил"],"notes":[{"id":"g10-1.4-n1","title":"Ион ба хийг таних арга","blocks":[{"t":"key","term":"Чанарын сорил","x":"Ион эсвэл бодисыг онцлог ажиглалтаар ялган таних туршилт."},{"t":"p","x":"Дөлний сорилд Na⁺ шар, K⁺ нил ягаан, Ca²⁺ тоосгон улаан өнгө үзүүлнэ. Цэвэр утас болон хяналтын дээж хэрэглэнэ; бохирдол үр дүнд нөлөөлнө."},{"t":"p","x":"Cu²⁺ нь OH⁻-той хөх, Fe³⁺ хүрэн, Fe²⁺ ногоон тунадас өгнө. Cl⁻-ийг азотын хүчлээр хүчиллэгжүүлсэн AgNO₃, SO₄²⁻-ийг давсны хүчлээр хүчиллэгжүүлсэн BaCl₂-оор шалгана."},{"t":"ex","q":"Шохойн ус булингартах урвалыг бич.","a":"Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O. Цагаан тунадас үүснэ."}]},{"id":"g10-1.4-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Хийг шууд үнэрлэж танихгүй. H₂, O₂, CO₂, NH₃-ийн сорил тус бүр өөр нотолгоо шаарддаг; хий ялгарах нь дангаараа таних сорил биш."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Хлоридын сорилын тунадас аль вэ?","a":"AgCl — Дөлний сорилд Na⁺ шар, K⁺ нил ягаан, Ca²⁺ тоосгон улаан өнгө үзүүлнэ. Цэвэр утас болон хяналтын дээж хэрэглэнэ; бохирдол үр дүнд нөлөөлнө."}]}],"flashcards":[{"id":"g10-1.4-c1","front":"Чанарын сорил гэж юу вэ?","back":"Ион эсвэл бодисыг онцлог ажиглалтаар ялган таних туршилт."},{"id":"g10-1.4-c2","front":"Шохойн ус булингартах урвалыг бич.","back":"Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O. Цагаан тунадас үүснэ."},{"id":"g10-1.4-c3","front":"Хлоридын сорилын тунадас аль вэ?","back":"AgCl"},{"id":"g10-1.4-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Хийг шууд үнэрлэж танихгүй. H₂, O₂, CO₂, NH₃-ийн сорил тус бүр өөр нотолгоо шаарддаг; хий ялгарах нь дангаараа таних сорил биш."}],"quiz":[{"id":"g10-1.4-q1","question":"Хлоридын сорилын тунадас аль вэ?","options":["Cu(OH)₂","AgCl","BaSO₄","Fe(OH)₃"],"answer":1,"explanation":"Дөлний сорилд Na⁺ шар, K⁺ нил ягаан, Ca²⁺ тоосгон улаан өнгө үзүүлнэ. Цэвэр утас болон хяналтын дээж хэрэглэнэ; бохирдол үр дүнд нөлөөлнө. Cu²⁺ нь OH⁻-той хөх, Fe³⁺ хүрэн, Fe²⁺ ногоон тунадас өгнө. Cl⁻-ийг азотын хүчлээр хүчиллэгжүүлсэн AgNO₃, SO₄²⁻-ийг давсны хүчлээр хүчиллэгжүүлсэн BaCl₂-оор шалгана."},{"id":"g10-1.4-q2","question":"CO₂-ийг шалгах урвалж аль вэ?","options":["Шохойн ус","NaCl уусмал","Цэвэр ус","Этанол"],"answer":0,"explanation":"CO₂ нь шохойн усанд CaCO₃-ийн цагаан тунадас үүсгэнэ."}],"questions":[{"id":"g10-1.4-s1","level":"medium","stem":"Шохойн ус булингартах урвалыг бич.","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O. Цагаан тунадас үүснэ.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O. Цагаан тунадас үүснэ."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Хийг шууд үнэрлэж танихгүй. H₂, O₂, CO₂, NH₃-ийн сорил тус бүр өөр нотолгоо шаарддаг; хий ялгарах нь дангаараа таних сорил биш."],"model":"Хийг шууд үнэрлэж танихгүй. H₂, O₂, CO₂, NH₃-ийн сорил тус бүр өөр нотолгоо шаарддаг; хий ялгарах нь дангаараа таних сорил биш."}]}],"practicals":[{"id":"g10-flame-prac","title":"Металлын ионы дөлний сорил","ref":"Хими X · х.34","aim":"Металлын ионы дөлний сорил — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Цэвэр утас ба хоосон сорил хэрэглэ.","Нэг давсны дээжийг утсанд авч дөлний өнгийг тэмдэглэ.","Өөр давсанд шилжих бүрд цэвэрлэж, өнгийг харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"Na⁺ шар, K⁺ нил ягаан, Li⁺ улаан, Ca²⁺ тоосгон улаан, Cu²⁺ хөх-ногоон.","labActivityId":"g10-flame"},{"id":"g10-cations-prac","title":"Катионы тунадасны сорил","ref":"Хими X · х.35–38","aim":"Катионы тунадасны сорил — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Тусдаа үүрүүдэд Cu²⁺, Fe²⁺, Fe³⁺-ийн уусмал ав.","NaOH-ийг бага хэмжээгээр нэмж өнгө ба тунадасыг тэмдэглэ.","Шинэ дээжээр NH₃-ийн сорил хий; илүүдэл урвалжийн нөлөөг тайлбарла."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"Cu(OH)₂ хөх, Fe(OH)₂ ногоон, Fe(OH)₃ хүрэн. Cu²⁺ илүүдэл NH₃-тай гүн хөх комплекс үүсгэнэ.","labActivityId":"g10-cations"},{"id":"g10-anions-prac","title":"Сульфат, хлорид ба карбонатын сорил","ref":"Хими X · х.37–38","aim":"Сульфат, хлорид ба карбонатын сорил — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Сульфат, хлорид ба карбонатыг тусдаа үүрэнд бэлтгэ.","Сульфатыг HCl-ээр хүчиллэгжүүлж BaCl₂ нэм. Хлоридыг HNO₃-оор хүчиллэгжүүлж AgNO₃ нэм; HCl хэрэглэвэл сорил бохирдоно.","Карбонатын тусдаа үүрэнд хүчил нэмж CO₂-ийг ажигла; шинэ дээжээр харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"SO₄²⁻ + Ba²⁺ → BaSO₄↓; Cl⁻ + Ag⁺ → AgCl↓. Карбонат хүчилтэй CO₂ өгнө.","labActivityId":"g10-anions"},{"id":"g10-gas-tests-prac","title":"CO₂ гаргах ба шохойн усны сорил","ref":"Хими X · х.39–40","aim":"CO₂ гаргах ба шохойн усны сорил — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т CaCO₃ ба ②-т HCl хий.","③-т шохойн ус нэмээд холих товч дар.","Хийн хэмжээ ба шохойн усны тунадасыг хэмж; H₂/O₂/NH₃-ийн өөр сорилуудыг тэмдэглэлтэй харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"CaCO₃ + 2HCl → CaCl₂ + CO₂ + H₂O; шохойн усанд CaCO₃ үүснэ.","labActivityId":"g10-gas-tests"}]},{"id":"2.1","chapterId":"2","title":"Химийн урвалын хурд","bookPages":"43–52","objectives":[{"id":"g10-2.1-o1","text":"20 секундэд 12 мл хий үүсвэл дундаж хурд хэд вэ?"},{"id":"g10-2.1-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Урвалын хурд"],"notes":[{"id":"g10-2.1-n1","title":"Химийн урвалын хурд","blocks":[{"t":"key","term":"Урвалын хурд","x":"Нэгж хугацаанд эх бодис зарцуулагдах эсвэл бүтээгдэхүүн үүсэх хэмжээ."},{"t":"p","x":"Хийн эзлэхүүн–хугацааны муруйн налуу нь тухайн хугацааны хурдыг илтгэнэ. Эхэнд налуу их, эх бодис дуусахад муруй тэгширнэ."},{"t":"p","x":"Концентрац, температур, хатуу бодисын гадаргуу ба катализатор үр дүнтэй мөргөлдөлтийн давтамжийг өөрчилнө. Катализатор бага идэвхжилийн энергитэй зам нээж өөрөө нийт дүнгээр зарцуулагдахгүй."},{"t":"ex","q":"20 секундэд 12 мл хий үүсвэл дундаж хурд хэд вэ?","a":"12/20=0.60 мл/с. Энэ нь дундаж хурд; агшин зуурын хурдтай заавал адил биш."}]},{"id":"g10-2.1-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Ижил хязгаарлагч бодистой үед катализатор эцсийн гарцыг өсгөхгүй. Хурд ба нийт бүтээгдэхүүний хэмжээг ялгаж тайлбарла."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Ижил масстай CaCO₃-ийг нунтаглахад юу өөрчлөгдөх вэ?","a":"Гадаргуугийн талбай — Хийн эзлэхүүн–хугацааны муруйн налуу нь тухайн хугацааны хурдыг илтгэнэ. Эхэнд налуу их, эх бодис дуусахад муруй тэгширнэ."}]}],"flashcards":[{"id":"g10-2.1-c1","front":"Урвалын хурд гэж юу вэ?","back":"Нэгж хугацаанд эх бодис зарцуулагдах эсвэл бүтээгдэхүүн үүсэх хэмжээ."},{"id":"g10-2.1-c2","front":"20 секундэд 12 мл хий үүсвэл дундаж хурд хэд вэ?","back":"12/20=0.60 мл/с. Энэ нь дундаж хурд; агшин зуурын хурдтай заавал адил биш."},{"id":"g10-2.1-c3","front":"Ижил масстай CaCO₃-ийг нунтаглахад юу өөрчлөгдөх вэ?","back":"Гадаргуугийн талбай"},{"id":"g10-2.1-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Ижил хязгаарлагч бодистой үед катализатор эцсийн гарцыг өсгөхгүй. Хурд ба нийт бүтээгдэхүүний хэмжээг ялгаж тайлбарла."}],"quiz":[{"id":"g10-2.1-q1","question":"Ижил масстай CaCO₃-ийг нунтаглахад юу өөрчлөгдөх вэ?","options":["Молийн масс","Нийт атомын тоо","Гадаргуугийн талбай","Элементийн төрөл"],"answer":2,"explanation":"Хийн эзлэхүүн–хугацааны муруйн налуу нь тухайн хугацааны хурдыг илтгэнэ. Эхэнд налуу их, эх бодис дуусахад муруй тэгширнэ. Концентрац, температур, хатуу бодисын гадаргуу ба катализатор үр дүнтэй мөргөлдөлтийн давтамжийг өөрчилнө. Катализатор бага идэвхжилийн энергитэй зам нээж өөрөө нийт дүнгээр зарцуулагдахгүй."},{"id":"g10-2.1-q2","question":"Катализатор ижил эх бодисын эцсийн гарцад ямар нөлөөтэй вэ?","options":["Заавал өсгөнө","Заавал бууруулна","Өөрөө дангаараа өөрчлөхгүй","Бүх эх бодисыг устгана"],"answer":2,"explanation":"Катализатор урвалын зам ба хурдыг өөрчилнө; стехиометрийн хязгаарыг өөрчлөхгүй."}],"questions":[{"id":"g10-2.1-s1","level":"medium","stem":"20 секундэд 12 мл хий үүсвэл дундаж хурд хэд вэ?","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["12/20=0.60 мл/с. Энэ нь дундаж хурд; агшин зуурын хурдтай заавал адил биш.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"12/20=0.60 мл/с. Энэ нь дундаж хурд; агшин зуурын хурдтай заавал адил биш."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Ижил хязгаарлагч бодистой үед катализатор эцсийн гарцыг өсгөхгүй. Хурд ба нийт бүтээгдэхүүний хэмжээг ялгаж тайлбарла."],"model":"Ижил хязгаарлагч бодистой үед катализатор эцсийн гарцыг өсгөхгүй. Хурд ба нийт бүтээгдэхүүний хэмжээг ялгаж тайлбарла."}]}],"practicals":[{"id":"g10-rate-zinc-prac","title":"Zn + HCl урвалын хийн хэмжээ–хугацаа","ref":"Хими X · х.45","aim":"Zn + HCl урвалын хийн хэмжээ–хугацаа — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т хатуу бодис, ②-т хүчил бэлтгэ; масс ба эзлэхүүнийг тэмдэглэ.","Хольж ижил хугацааны алхамтай хийн хэмжилт ав.","Шинэ угсралт бэлтгэн нэг хүчин зүйл өөрчил; концентрацыг усаар шингэрүүлж, гадаргууг сонгосон савны нунтаглах удирдлагаар өөрчил."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"Хурд ба эцсийн хийн гарцыг ялга. Ижил хэмжээгээр авсан хязгаарлагч бодис эцсийн гарцыг тогтооно.","labActivityId":"g10-rate-zinc"},{"id":"g10-rate-concentration-prac","title":"Хүчлийн концентрацыг өөрчлөх","ref":"Хими X · х.47–48","aim":"Хүчлийн концентрацыг өөрчлөх — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т хатуу бодис, ②-т хүчил бэлтгэ; масс ба эзлэхүүнийг тэмдэглэ.","Хольж ижил хугацааны алхамтай хийн хэмжилт ав.","Шинэ угсралт бэлтгэн нэг хүчин зүйл өөрчил; концентрацыг усаар шингэрүүлж, гадаргууг сонгосон савны нунтаглах удирдлагаар өөрчил."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"Хурд ба эцсийн хийн гарцыг ялга. Ижил хэмжээгээр авсан хязгаарлагч бодис эцсийн гарцыг тогтооно.","labActivityId":"g10-rate-concentration"},{"id":"g10-rate-surface-prac","title":"CaCO₃-ийн гадаргуугийн нөлөө","ref":"Хими X · х.49–50","aim":"CaCO₃-ийн гадаргуугийн нөлөө — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т хатуу бодис, ②-т хүчил бэлтгэ; масс ба эзлэхүүнийг тэмдэглэ.","Хольж ижил хугацааны алхамтай хийн хэмжилт ав.","Шинэ угсралт бэлтгэн нэг хүчин зүйл өөрчил; концентрацыг усаар шингэрүүлж, гадаргууг сонгосон савны нунтаглах удирдлагаар өөрчил."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"Хурд ба эцсийн хийн гарцыг ялга. Ижил хэмжээгээр авсан хязгаарлагч бодис эцсийн гарцыг тогтооно.","labActivityId":"g10-rate-surface"},{"id":"g10-thiosulfate-prac","title":"Тиосульфат–хүчил: хэрээс алга болох хугацаа","ref":"Хими X · х.49","aim":"Тиосульфат–хүчил: хэрээс алга болох хугацаа — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т 10 мл тиосульфат, ②-т 5 мл HCl бэлтгэ.","Термостатаар эхний температурыг сонгож ажиллуулах/холих товч дар.","Хүхрийн тунадас үүсч хэрээс далдрах хугацааг шинэ температуртай оролдлоготой харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Na₂S₂O₃ + 2HCl → 2NaCl + SO₂ + S↓ + H₂O. SO₂ хортой; коэффициентүүд нь сургалтын жишээ.","labActivityId":"g10-thiosulfate"},{"id":"g10-catalysts-prac","title":"Пероксидын задрал ба катализатор","ref":"Хими X · х.51","aim":"Пероксидын задрал ба катализатор — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Пероксидын ижил хэмжээтэй хяналтын дээжийг катализаторгүй хэмж.","Шинэ дээжид нэг оксид нэмж ижил хугацаанд O₂-ийг хэмж.","Катализаторын төрлийг өөрчилж харьцуул; сургалтын хурдны коэффициентийг бодит эрэмбэ гэж үзэхгүй."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"2H₂O₂ → 2H₂O + O₂. Катализатор нийт гарцыг нэмэгдүүлэхгүй.","labActivityId":"g10-catalysts"}]},{"id":"2.2","chapterId":"2","title":"Эргэх урвал ба химийн тэнцвэр","bookPages":"53–60","objectives":[{"id":"g10-2.2-o1","text":"N₂ + 3H₂ ⇌ 2NH₃ урвалд даралт өсөхөд аль чиглэл дэмжигдэх вэ?"},{"id":"g10-2.2-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Динамик тэнцвэр"],"notes":[{"id":"g10-2.2-n1","title":"Эргэх урвал ба химийн тэнцвэр","blocks":[{"t":"key","term":"Динамик тэнцвэр","x":"Битүү системд шууд ба буцах урвалын хурд тэнцсэн төлөв."},{"t":"p","x":"Тэнцвэрт урвал зогсдоггүй. Эх ба бүтээгдэхүүний концентрацууд хугацааны турш тогтвортой боловч хоорондоо заавал тэнцүү биш."},{"t":"p","x":"Концентрац, температур, хийд даралт өөрчлөхөд тэнцвэр шинэ нөхцөлд шилжинэ. Катализатор хоёр чиглэлийг хурдасгаж тэнцвэрийн байршлыг өөрчлөхгүй."},{"t":"ex","q":"N₂ + 3H₂ ⇌ 2NH₃ урвалд даралт өсөхөд аль чиглэл дэмжигдэх вэ?","a":"Хийн молийн тоо 4-өөс 2 болж буурах баруун чиглэл дэмжигдэнэ; температур тогтмол гэж үзэв."}]},{"id":"g10-2.2-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Өнгөний эрчим нь хэмжээ ба шингэрүүлэлтээс хамаарна. Өнгө өөрчлөгдөхийг зөвхөн нэг хүчин зүйлээр тэнцвэрийн нотолгоо гэж үзэхгүй."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Тэнцвэрийн үед аль нь зөв вэ?","a":"Хоёр чиглэлийн хурд тэнцүү — Тэнцвэрт урвал зогсдоггүй. Эх ба бүтээгдэхүүний концентрацууд хугацааны турш тогтвортой боловч хоорондоо заавал тэнцүү биш."}]}],"flashcards":[{"id":"g10-2.2-c1","front":"Динамик тэнцвэр гэж юу вэ?","back":"Битүү системд шууд ба буцах урвалын хурд тэнцсэн төлөв."},{"id":"g10-2.2-c2","front":"N₂ + 3H₂ ⇌ 2NH₃ урвалд даралт өсөхөд аль чиглэл дэмжигдэх вэ?","back":"Хийн молийн тоо 4-өөс 2 болж буурах баруун чиглэл дэмжигдэнэ; температур тогтмол гэж үзэв."},{"id":"g10-2.2-c3","front":"Тэнцвэрийн үед аль нь зөв вэ?","back":"Хоёр чиглэлийн хурд тэнцүү"},{"id":"g10-2.2-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Өнгөний эрчим нь хэмжээ ба шингэрүүлэлтээс хамаарна. Өнгө өөрчлөгдөхийг зөвхөн нэг хүчин зүйлээр тэнцвэрийн нотолгоо гэж үзэхгүй."}],"quiz":[{"id":"g10-2.2-q1","question":"Тэнцвэрийн үед аль нь зөв вэ?","options":["Концентрацууд тэнцүү","Хоёр чиглэлийн хурд тэнцүү","Урвал зогссон","Бүтээгдэхүүн байхгүй"],"answer":1,"explanation":"Тэнцвэрт урвал зогсдоггүй. Эх ба бүтээгдэхүүний концентрацууд хугацааны турш тогтвортой боловч хоорондоо заавал тэнцүү биш. Концентрац, температур, хийд даралт өөрчлөхөд тэнцвэр шинэ нөхцөлд шилжинэ. Катализатор хоёр чиглэлийг хурдасгаж тэнцвэрийн байршлыг өөрчлөхгүй."},{"id":"g10-2.2-q2","question":"Экзотерм шууд урвалын температурыг өсгөхөд ямар чиглэл дэмжигдэх вэ?","options":["Эндотерм буцах чиглэл","Экзотерм шууд чиглэл","Урвал заавал зогсоно","Катализатор үүснэ"],"answer":0,"explanation":"Температур нэмэгдэхэд нэмсэн дулааныг шингээх буцах чиглэл дэмжигдэнэ."}],"questions":[{"id":"g10-2.2-s1","level":"medium","stem":"N₂ + 3H₂ ⇌ 2NH₃ урвалд даралт өсөхөд аль чиглэл дэмжигдэх вэ?","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["Хийн молийн тоо 4-өөс 2 болж буурах баруун чиглэл дэмжигдэнэ; температур тогтмол гэж үзэв.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"Хийн молийн тоо 4-өөс 2 болж буурах баруун чиглэл дэмжигдэнэ; температур тогтмол гэж үзэв."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Өнгөний эрчим нь хэмжээ ба шингэрүүлэлтээс хамаарна. Өнгө өөрчлөгдөхийг зөвхөн нэг хүчин зүйлээр тэнцвэрийн нотолгоо гэж үзэхгүй."],"model":"Өнгөний эрчим нь хэмжээ ба шингэрүүлэлтээс хамаарна. Өнгө өөрчлөгдөхийг зөвхөн нэг хүчин зүйлээр тэнцвэрийн нотолгоо гэж үзэхгүй."}]}],"practicals":[{"id":"g10-hydrate-prac","title":"CuSO₄-ийн гидратжилтын эргэх хувирал","ref":"Хими X · х.53–54","aim":"CuSO₄-ийн гидратжилтын эргэх хувирал — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т CuSO₄·5H₂O-ийн хэмжсэн талст хий.","180°C термостат ба халаалт асааж ажиллуул; цагаан усгүй давс ба ③ конденсатыг ажигла.","Хөргөж усны хэмжсэн хэсэг нэмэн хөх гидрат буцаж үүсэхийг харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Усгүй CuSO₄ цагаан, гидрат хөх. Загварын өнгөний индекс бодит гидратын фазын тэнцвэрийн тооцоо биш.","labActivityId":"g10-hydrate"},{"id":"g10-equilibrium-prac","title":"Концентрац ба тэнцвэр: төмөр–тиоцианат","ref":"Нэмэлт тэнцвэрийн загвар · Хими X, 2.2 сэдэвтэй холбов","aim":"Концентрац ба тэнцвэр: төмөр–тиоцианат — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т FeCl₃, ②-т KSCN-ийн бага хэмжээг бэлтгэ.","Ажиллуулах/холих товч дарж улаан комплексийн хэмжээг тэмдэглэ.","Нэмэлт Fe³⁺, SCN⁻ эсвэл усаар нэг нөхцөлийг өөрчлөн харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Улаан комплексийн хэмжээ эхний бодисоор хязгаарлагдана. K=1000 л/моль нь сургалтын тогтмол.","labActivityId":"g10-equilibrium"},{"id":"g10-no2-equilibrium-prac","title":"N₂O₄ ⇌ NO₂: температур ба эзлэхүүн","ref":"Хими X · х.54–57","aim":"N₂O₄ ⇌ NO₂: температур ба эзлэхүүн — нэг нөхцөлийг өөрчилж тэнцвэрийн хэмжээг харьцуул.","steps":["①-т NO₂ эсвэл N₂O₄-ийн хэмжсэн хийг дамжуул.","Багажийг ажиллуулж поршений эзлэхүүн эсвэл термостатыг өөрчил.","Бор NO₂, өнгөгүй N₂O₄-ийн моль ба даралтыг хэмжиж харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. N₂O₄ ⇌ 2NO₂. Kc(25°C)=0.010 моль/л, ΔH=57 кЖ/моль гэсэн сургалтын жишээ; NO₂-ийн бор өнгө концентрацаас хамаарна.","labActivityId":"g10-no2-equilibrium"},{"id":"g10-haber-prac","title":"Аммиакийн тэнцвэр: даралт ба температур","ref":"Хими X · х.58–60","aim":"Аммиакийн тэнцвэр: даралт ба температур — нэг нөхцөлийг өөрчилж тэнцвэрийн хэмжээг харьцуул.","steps":["① ба ②-оор N₂:H₂ = 1:3 харьцаатай хийн хэсгүүд, Fe катализатор бэлтгэ.","Ажиллуулж битүү поршений эзлэхүүн, температурын нэгийг өөрчил.","NH₃-ийн үүсэх хэмжээ, хийн нөөц ба даралтыг харьцуул; тэнцвэр ба хурдыг ялга."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. N₂ + 3H₂ ⇌ 2NH₃. Идеал хийн Kp(700K)=10⁻⁴, ΔH=−92.4 кЖ/моль гэсэн жишээ; бодит үйлдвэрийн гарц, кинетик биш.","labActivityId":"g10-haber"}]},{"id":"2.3","chapterId":"2","title":"Цахилгаан хими","bookPages":"61–71","objectives":[{"id":"g10-2.3-o1","text":"Cu²⁺-ийн катодын хагас урвалыг бич."},{"id":"g10-2.3-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Электролиз"],"notes":[{"id":"g10-2.3-n1","title":"Цахилгаан хими","blocks":[{"t":"key","term":"Электролиз","x":"Гаднын цахилгаан гүйдлээр химийн хувирал явуулах үйл явц."},{"t":"p","x":"Электролитийн ионууд гүйдэл зөөнө. Электрон гадаад утсаар хөдөлнө. Катод дээр ангижрах, анод дээр исэлдэх урвал явагдана."},{"t":"p","x":"Гальваны хэлхээ аяндаа явагдах урвалаас цахилгаан гаргана. Электролиз гаднаас энерги авна. CuSO₄-ийн уусмалд инерт анод ба зэс анодын бүтээгдэхүүн ялгаатай."},{"t":"ex","q":"Cu²⁺-ийн катодын хагас урвалыг бич.","a":"Cu²⁺ + 2e⁻ → Cu. Нэг моль Cu-д хоёр моль электрон хэрэгтэй."}]},{"id":"g10-2.3-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Усан уусмал ба хайлмалын электролизийг ялга. Ус өрсөлдөгч урвалж тул NaCl-ийн усан уусмалаас металл Na ялгарахгүй."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Анод дээр ямар үйл явц явагддаг вэ?","a":"Исэлдэх — Электролитийн ионууд гүйдэл зөөнө. Электрон гадаад утсаар хөдөлнө. Катод дээр ангижрах, анод дээр исэлдэх урвал явагдана."}]}],"flashcards":[{"id":"g10-2.3-c1","front":"Электролиз гэж юу вэ?","back":"Гаднын цахилгаан гүйдлээр химийн хувирал явуулах үйл явц."},{"id":"g10-2.3-c2","front":"Cu²⁺-ийн катодын хагас урвалыг бич.","back":"Cu²⁺ + 2e⁻ → Cu. Нэг моль Cu-д хоёр моль электрон хэрэгтэй."},{"id":"g10-2.3-c3","front":"Анод дээр ямар үйл явц явагддаг вэ?","back":"Исэлдэх"},{"id":"g10-2.3-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Усан уусмал ба хайлмалын электролизийг ялга. Ус өрсөлдөгч урвалж тул NaCl-ийн усан уусмалаас металл Na ялгарахгүй."}],"quiz":[{"id":"g10-2.3-q1","question":"Анод дээр ямар үйл явц явагддаг вэ?","options":["Ангижрах","Исэлдэх","Зөвхөн уусах","Заавал устөрөгч ялгарах"],"answer":1,"explanation":"Электролитийн ионууд гүйдэл зөөнө. Электрон гадаад утсаар хөдөлнө. Катод дээр ангижрах, анод дээр исэлдэх урвал явагдана. Гальваны хэлхээ аяндаа явагдах урвалаас цахилгаан гаргана. Электролиз гаднаас энерги авна. CuSO₄-ийн уусмалд инерт анод ба зэс анодын бүтээгдэхүүн ялгаатай."},{"id":"g10-2.3-q2","question":"Cu²⁺-оос 1 моль Cu гаргахад хэдэн моль электрон хэрэгтэй вэ?","options":["0.5","1","2","4"],"answer":2,"explanation":"Cu²⁺ + 2e⁻ → Cu; хоёр электрон авна."}],"questions":[{"id":"g10-2.3-s1","level":"medium","stem":"Cu²⁺-ийн катодын хагас урвалыг бич.","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["Cu²⁺ + 2e⁻ → Cu. Нэг моль Cu-д хоёр моль электрон хэрэгтэй.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"Cu²⁺ + 2e⁻ → Cu. Нэг моль Cu-д хоёр моль электрон хэрэгтэй."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Усан уусмал ба хайлмалын электролизийг ялга. Ус өрсөлдөгч урвалж тул NaCl-ийн усан уусмалаас металл Na ялгарахгүй."],"model":"Усан уусмал ба хайлмалын электролизийг ялга. Ус өрсөлдөгч урвалж тул NaCl-ийн усан уусмалаас металл Na ялгарахгүй."}]}],"practicals":[{"id":"g10-ion-migration-prac","title":"U хоолой дахь ионы шилжилт","ref":"Хими X · х.63","aim":"U хоолой дахь ионы шилжилт — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["① U хоолойд CuCrO₄-ийн уусмал хий.","DC хүчдэлийг 0 В-оос 3 В болгон өөрчилж хэлхээг залга.","Цэнхэр катион ба шар анионы туйл руу шилжих дүрслэлийг харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Энэ нь шилжилтийн схем; Cr(VI)-тай бодит туршилт биш, электродын бүтээгдэхүүнийг тооцоогүй.","labActivityId":"g10-ion-migration"},{"id":"g10-galvanic-prac","title":"Zn–Cu гальваны хэлхээ","ref":"Хими X · х.64–65","aim":"Zn–Cu гальваны хэлхээ — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т Zn ба ZnSO₄, ②-т Cu ба CuSO₄, ③-т NaCl давсан гүүр бэлтгэ.","Багажийг ажиллуулж нээлттэй хэлхээний хүчдэл унш.","Ачааллыг холбож эсэргүүцлийг өөрчил; Zn зарцуулалт ба Cu ялгаралтыг хэмж."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Zn → Zn²⁺ + 2e⁻; Cu²⁺ + 2e⁻ → Cu. 25°C-д E°=1.10 В, Нернстийн хялбаршуулсан загвар.","labActivityId":"g10-galvanic"},{"id":"g10-electrolysis-prac","title":"CuSO₄-ийн электролиз: инерт ба зэс анод","ref":"Хими X · х.67–71","aim":"CuSO₄-ийн электролиз: инерт ба зэс анод — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т CuSO₄-ийн электролит, ② ба ③-т графитан электрод хий.","DC хүчдэл ба гүйдлийг тохируулж хэлхээг залга.","Катодын масс, анодын O₂ ба цэнэгийг хэмж; шинэ оролдлогод Cu анодоор сольж харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. M²⁺ + 2e⁻ → M. Уусдаг анодод M → M²⁺ + 2e⁻. Инерт анодод 2H₂O → O₂ + 4H⁺ + 4e⁻; 100% гүйдлийн гарцын загвар.","labActivityId":"g10-electrolysis"},{"id":"g10-electroplating-prac","title":"Никелиэр цахилгаан бүрэх","ref":"Хими X · х.71","aim":"Никелиэр цахилгаан бүрэх — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т NiSO₄, ②-т Fe эдлэл, ③-т Ni анод хий.","DC гүйдэл ба хүчдэлийг тохируулж хэлхээг залга.","Ижил гүйдэлд хугацааг өөрчилж катодын Ni бүрхүүл ба анодын зарцуулалтыг хэмж."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. M²⁺ + 2e⁻ → M. Уусдаг анодод M → M²⁺ + 2e⁻. Инерт анодод 2H₂O → O₂ + 4H⁺ + 4e⁻; 100% гүйдлийн гарцын загвар.","labActivityId":"g10-electroplating"}]},{"id":"3.1","chapterId":"3","title":"Металл ба хайлш","bookPages":"76–86","objectives":[{"id":"g10-3.1-o1","text":"Zn-ийг CuSO₄-д хийхэд юу ажиглагдах вэ?"},{"id":"g10-3.1-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Хайлш"],"notes":[{"id":"g10-3.1-n1","title":"Металл ба хайлш","blocks":[{"t":"key","term":"Хайлш","x":"Металлын нэг эсвэл хэд хэдэн элементтэй үүсгэсэн холимог."},{"t":"p","x":"Металлын идэвхийн эгнээ нь халах урвал, хүдрээс гаргах аргыг сонгоход тусална. Идэвхтэй металл идэвх багатай металлын ионыг ангижруулж чадна."},{"t":"p","x":"Хайлшийн өөр хэмжээтэй атомууд үе давхаргын гулсалтыг саатуулж хатуулаг өөрчилнө. Зэврэлтэд ус, хүчилтөрөгч хэрэгтэй; бүрхүүл ба золиосын металл өөр механизмаар хамгаална."},{"t":"ex","q":"Zn-ийг CuSO₄-д хийхэд юу ажиглагдах вэ?","a":"Zn + CuSO₄ → ZnSO₄ + Cu. Цайр зарцуулагдаж зэс ялгарна; хөх өнгө суларна."}]},{"id":"g10-3.1-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Өндөр идэвхтэй металлыг нүүрстөрөгчөөр ангижруулах боломжгүй байж болно. Хүдэр, энерги, электролизийн нөхцөлийг хамт авч үзнэ."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Төмрийг сэвтэй үед ч золиослон хамгаалах металл аль вэ?","a":"Zn — Металлын идэвхийн эгнээ нь халах урвал, хүдрээс гаргах аргыг сонгоход тусална. Идэвхтэй металл идэвх багатай металлын ионыг ангижруулж чадна."}]}],"flashcards":[{"id":"g10-3.1-c1","front":"Хайлш гэж юу вэ?","back":"Металлын нэг эсвэл хэд хэдэн элементтэй үүсгэсэн холимог."},{"id":"g10-3.1-c2","front":"Zn-ийг CuSO₄-д хийхэд юу ажиглагдах вэ?","back":"Zn + CuSO₄ → ZnSO₄ + Cu. Цайр зарцуулагдаж зэс ялгарна; хөх өнгө суларна."},{"id":"g10-3.1-c3","front":"Төмрийг сэвтэй үед ч золиослон хамгаалах металл аль вэ?","back":"Zn"},{"id":"g10-3.1-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Өндөр идэвхтэй металлыг нүүрстөрөгчөөр ангижруулах боломжгүй байж болно. Хүдэр, энерги, электролизийн нөхцөлийг хамт авч үзнэ."}],"quiz":[{"id":"g10-3.1-q1","question":"Төмрийг сэвтэй үед ч золиослон хамгаалах металл аль вэ?","options":["Cu","Ag","Au","Zn"],"answer":3,"explanation":"Металлын идэвхийн эгнээ нь халах урвал, хүдрээс гаргах аргыг сонгоход тусална. Идэвхтэй металл идэвх багатай металлын ионыг ангижруулж чадна. Хайлшийн өөр хэмжээтэй атомууд үе давхаргын гулсалтыг саатуулж хатуулаг өөрчилнө. Зэврэлтэд ус, хүчилтөрөгч хэрэгтэй; бүрхүүл ба золиосын металл өөр механизмаар хамгаална."},{"id":"g10-3.1-q2","question":"Fe-ийг CuSO₄-ийн уусмалд хийхэд аль нь ангижрах вэ?","options":["Fe","Cu²⁺","SO₄²⁻","Бүгд"],"answer":1,"explanation":"Fe электрон өгч Fe²⁺ болно; Cu²⁺ электрон авч металл Cu болно."}],"questions":[{"id":"g10-3.1-s1","level":"medium","stem":"Zn-ийг CuSO₄-д хийхэд юу ажиглагдах вэ?","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["Zn + CuSO₄ → ZnSO₄ + Cu. Цайр зарцуулагдаж зэс ялгарна; хөх өнгө суларна.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"Zn + CuSO₄ → ZnSO₄ + Cu. Цайр зарцуулагдаж зэс ялгарна; хөх өнгө суларна."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Өндөр идэвхтэй металлыг нүүрстөрөгчөөр ангижруулах боломжгүй байж болно. Хүдэр, энерги, электролизийн нөхцөлийг хамт авч үзнэ."],"model":"Өндөр идэвхтэй металлыг нүүрстөрөгчөөр ангижруулах боломжгүй байж болно. Хүдэр, энерги, электролизийн нөхцөлийг хамт авч үзнэ."}]}],"practicals":[{"id":"g10-displacement-prac","title":"Металлын идэвх ба халах урвал","ref":"Хими X · х.76–80","aim":"Металлын идэвх ба халах урвал — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Тусдаа саванд ижил хэмжээтэй металлын давсны уусмал ав.","Металлыг нэмж өнгө, бүрхүүл ба үлдэгдлийг хэмж.","Халах болон урвалгүй хосыг харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"Zn + Cu²⁺ → Zn²⁺ + Cu; Cu + 2Ag⁺ → Cu²⁺ + 2Ag.","labActivityId":"g10-displacement"},{"id":"g10-corrosion-prac","title":"Зэврэлтийн хамгаалалтыг харьцуулах","ref":"Хими X · х.82–84","aim":"Зэврэлтийн хамгаалалтыг харьцуулах — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Тусдаа үүрэнд төмөр ба ижил ус хий.","Нэгийг тосоор тусгаарлаж, бусдад Zn эсвэл Cu хүрэлцүүл.","Ижил хугацаанд зэврэлтийн индексийг харьцуул; сэвтэй бүрхүүлийг давтан шалга."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"Zn золиослон хамгаална; Cu-тай хүрэлцэх нь төмрийн зэврэлтийг түргэсгэж болно. Индекс нь бодит хурд биш.","labActivityId":"g10-corrosion"}]},{"id":"3.2","chapterId":"3","title":"Карбонат","bookPages":"87–92","objectives":[{"id":"g10-3.2-o1","text":"0.010 моль CaCO₃ бүрэн задрахад хэдэн моль CO₂ үүсэх вэ?"},{"id":"g10-3.2-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Шохойн эргэлт"],"notes":[{"id":"g10-3.2-n1","title":"Карбонат","blocks":[{"t":"key","term":"Шохойн эргэлт","x":"CaCO₃, CaO, Ca(OH)₂-ийн хоорондын хувирлын холбоо."},{"t":"p","x":"CaCO₃-ийг хүчтэй халаахад CaO ба CO₂ үүснэ. CaO-д ус нэмэхэд дулаан ялгарч Ca(OH)₂ үүснэ. Эдгээр нь өөр өөр бодис."},{"t":"p","x":"Карбонат хүчилтэй урвалд орж давс, ус, CO₂ өгнө. Шохойн усаар CO₂-ийг танина. Карбонатын өндөр температурын задралыг энгийн усан баннаар хийхгүй."},{"t":"ex","q":"0.010 моль CaCO₃ бүрэн задрахад хэдэн моль CO₂ үүсэх вэ?","a":"CaCO₃ → CaO + CO₂. 1:1 тул 0.010 моль CO₂."}]},{"id":"g10-3.2-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Шохойн чулуу хүчиллэг хөрс ба үйлдвэрийн хүчиллэг хийг саармагжуулж болно. Бодит тунг хөрсний шинжилгээ, процессын нөхцөлөөр тогтооно."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"CaO + H₂O урвалын бүтээгдэхүүн аль вэ?","a":"Ca(OH)₂ — CaCO₃-ийг хүчтэй халаахад CaO ба CO₂ үүснэ. CaO-д ус нэмэхэд дулаан ялгарч Ca(OH)₂ үүснэ. Эдгээр нь өөр өөр бодис."}]}],"flashcards":[{"id":"g10-3.2-c1","front":"Шохойн эргэлт гэж юу вэ?","back":"CaCO₃, CaO, Ca(OH)₂-ийн хоорондын хувирлын холбоо."},{"id":"g10-3.2-c2","front":"0.010 моль CaCO₃ бүрэн задрахад хэдэн моль CO₂ үүсэх вэ?","back":"CaCO₃ → CaO + CO₂. 1:1 тул 0.010 моль CO₂."},{"id":"g10-3.2-c3","front":"CaO + H₂O урвалын бүтээгдэхүүн аль вэ?","back":"Ca(OH)₂"},{"id":"g10-3.2-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Шохойн чулуу хүчиллэг хөрс ба үйлдвэрийн хүчиллэг хийг саармагжуулж болно. Бодит тунг хөрсний шинжилгээ, процессын нөхцөлөөр тогтооно."}],"quiz":[{"id":"g10-3.2-q1","question":"CaO + H₂O урвалын бүтээгдэхүүн аль вэ?","options":["CaCO₃","CaCl₂","Ca(OH)₂","CaSO₄"],"answer":2,"explanation":"CaCO₃-ийг хүчтэй халаахад CaO ба CO₂ үүснэ. CaO-д ус нэмэхэд дулаан ялгарч Ca(OH)₂ үүснэ. Эдгээр нь өөр өөр бодис. Карбонат хүчилтэй урвалд орж давс, ус, CO₂ өгнө. Шохойн усаар CO₂-ийг танина. Карбонатын өндөр температурын задралыг энгийн усан баннаар хийхгүй."},{"id":"g10-3.2-q2","question":"CaCO₃-ийн дулааны задралын бүтээгдэхүүн аль вэ?","options":["Ca ба CO₃","CaO ба CO₂","Ca(OH)₂ ба H₂","CaCl₂ ба O₂"],"answer":1,"explanation":"CaCO₃ → CaO + CO₂. Нэг моль карбонатаас нэг моль хий үүснэ."}],"questions":[{"id":"g10-3.2-s1","level":"medium","stem":"0.010 моль CaCO₃ бүрэн задрахад хэдэн моль CO₂ үүсэх вэ?","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["CaCO₃ → CaO + CO₂. 1:1 тул 0.010 моль CO₂.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"CaCO₃ → CaO + CO₂. 1:1 тул 0.010 моль CO₂."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Шохойн чулуу хүчиллэг хөрс ба үйлдвэрийн хүчиллэг хийг саармагжуулж болно. Бодит тунг хөрсний шинжилгээ, процессын нөхцөлөөр тогтооно."],"model":"Шохойн чулуу хүчиллэг хөрс ба үйлдвэрийн хүчиллэг хийг саармагжуулж болно. Бодит тунг хөрсний шинжилгээ, процессын нөхцөлөөр тогтооно."}]}],"practicals":[{"id":"g10-limestone-prac","title":"Шохойн чулууны гурван хувирал","ref":"Хими X · х.88","aim":"Шохойн чулууны гурван хувирал — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т CaCO₃ хийж термостатыг 1000°C болгон халааж ажиллуул.","Хөргөсний дараа хэмжсэн ус нэмэн CaO-оос Ca(OH)₂ үүсэхийг ажигла.","CO₂-ийн хэмжсэн хэсэг дамжуулж CaCO₃ тунадас буцаж үүсэхийг шалга."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. CaCO₃ → CaO + CO₂; CaO + H₂O → Ca(OH)₂; Ca(OH)₂ + CO₂ → CaCO₃ + H₂O. Өндөр температурын зуух шаардлагатай.","labActivityId":"g10-limestone"},{"id":"g10-carbonate-prac","title":"Карбонат ба хүчил: хязгаарлагч бодис","ref":"Хими X · х.89–92","aim":"Карбонат ба хүчил: хязгаарлагч бодис — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Карбонатын массыг ижил байлгаж хүчлийн хэмжээг хоёр нөхцөлд сонго.","① ба ②-ыг хольж хий цуглуул; ③-т шохойн ус хий.","Эцсийн хийн хэмжээ ба үлдсэн хатуу бодисыг харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"n(CO₂)≤min(n(CaCO₃),n(HCl)/2).","labActivityId":"g10-carbonate"}]},{"id":"3.3","chapterId":"3","title":"Хүхэр","bookPages":"93–98","objectives":[{"id":"g10-3.3-o1","text":"Халуун концентрацтай H₂SO₄ зэстэй урвалд ороход H₂ ялгарах уу?"},{"id":"g10-3.3-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Контактын арга"],"notes":[{"id":"g10-3.3-n1","title":"Хүхэр","blocks":[{"t":"key","term":"Контактын арга","x":"SO₂-ийг катализатороор SO₃ болгон исэлдүүлж хүхрийн хүчил үйлдвэрлэх арга."},{"t":"p","x":"Хүхэр шар хатуу металл биш. Хүхэр шатахад SO₂ үүсэж, цааш хүчилтөрөгчтэй эргэх урвалаар SO₃ үүснэ. SO₂ нь хүчиллэг оксид."},{"t":"p","x":"2SO₂ + O₂ ⇌ 2SO₃ урвал экзотерм. Бага температур гарцыг дэмжих боловч хурд удааширна; үйлдвэрийн температур нь хурд ба гарцын тохиролцоо."},{"t":"ex","q":"Халуун концентрацтай H₂SO₄ зэстэй урвалд ороход H₂ ялгарах уу?","a":"Үгүй. Cu + 2H₂SO₄ → CuSO₄ + SO₂ + 2H₂O. Хүчил исэлдүүлэгчээр оролцоно."}]},{"id":"g10-3.3-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Шингэрүүлсэн болон концентрацтай хүхрийн хүчлийн урвал адил биш. SO₂-ийг үнэрлэхгүй; энэ хэсгийн аюултай ажиллагааг зөвхөн виртуал загвараар судална."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Контактын шатны урвал аль вэ?","a":"2SO₂ + O₂ ⇌ 2SO₃ — Хүхэр шар хатуу металл биш. Хүхэр шатахад SO₂ үүсэж, цааш хүчилтөрөгчтэй эргэх урвалаар SO₃ үүснэ. SO₂ нь хүчиллэг оксид."}]}],"flashcards":[{"id":"g10-3.3-c1","front":"Контактын арга гэж юу вэ?","back":"SO₂-ийг катализатороор SO₃ болгон исэлдүүлж хүхрийн хүчил үйлдвэрлэх арга."},{"id":"g10-3.3-c2","front":"Халуун концентрацтай H₂SO₄ зэстэй урвалд ороход H₂ ялгарах уу?","back":"Үгүй. Cu + 2H₂SO₄ → CuSO₄ + SO₂ + 2H₂O. Хүчил исэлдүүлэгчээр оролцоно."},{"id":"g10-3.3-c3","front":"Контактын шатны урвал аль вэ?","back":"2SO₂ + O₂ ⇌ 2SO₃"},{"id":"g10-3.3-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Шингэрүүлсэн болон концентрацтай хүхрийн хүчлийн урвал адил биш. SO₂-ийг үнэрлэхгүй; энэ хэсгийн аюултай ажиллагааг зөвхөн виртуал загвараар судална."}],"quiz":[{"id":"g10-3.3-q1","question":"Контактын шатны урвал аль вэ?","options":["SO₂ + H₂ → S + H₂O","2SO₂ + O₂ ⇌ 2SO₃","S + H₂ → H₂S","SO₃ → S + O₂"],"answer":1,"explanation":"Хүхэр шар хатуу металл биш. Хүхэр шатахад SO₂ үүсэж, цааш хүчилтөрөгчтэй эргэх урвалаар SO₃ үүснэ. SO₂ нь хүчиллэг оксид. 2SO₂ + O₂ ⇌ 2SO₃ урвал экзотерм. Бага температур гарцыг дэмжих боловч хурд удааширна; үйлдвэрийн температур нь хурд ба гарцын тохиролцоо."},{"id":"g10-3.3-q2","question":"SO₂-ийн усан орчин ямар шинжтэй вэ?","options":["Суурилаг","Хүчиллэг","Заавал саармаг","Металл"],"answer":1,"explanation":"SO₂ нь хүчиллэг оксид; усан орчны хүчиллэгийг нэмэгдүүлнэ."}],"questions":[{"id":"g10-3.3-s1","level":"medium","stem":"Халуун концентрацтай H₂SO₄ зэстэй урвалд ороход H₂ ялгарах уу?","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["Үгүй. Cu + 2H₂SO₄ → CuSO₄ + SO₂ + 2H₂O. Хүчил исэлдүүлэгчээр оролцоно.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"Үгүй. Cu + 2H₂SO₄ → CuSO₄ + SO₂ + 2H₂O. Хүчил исэлдүүлэгчээр оролцоно."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Шингэрүүлсэн болон концентрацтай хүхрийн хүчлийн урвал адил биш. SO₂-ийг үнэрлэхгүй; энэ хэсгийн аюултай ажиллагааг зөвхөн виртуал загвараар судална."],"model":"Шингэрүүлсэн болон концентрацтай хүхрийн хүчлийн урвал адил биш. SO₂-ийг үнэрлэхгүй; энэ хэсгийн аюултай ажиллагааг зөвхөн виртуал загвараар судална."}]}],"practicals":[{"id":"g10-sulfur-acid-prac","title":"Cu ба концентрацтай H₂SO₄","ref":"Хими X · х.96","aim":"Cu ба концентрацтай H₂SO₄ — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т Cu, ②-т концентрацтай H₂SO₄-ийн бага хэсэг хий.","Термостатыг 90°C болгож халаалт асаан ажиллуулж холь.","CuSO₄ ба SO₂-ийн хэмжээг тэмдэглэж шингэрүүлсэн хүчлийн хяналттай харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Cu + 2H₂SO₄(конц) → CuSO₄ + SO₂ + 2H₂O. Зөвхөн виртуал үзүүлэн; бодит SO₂ үүсгэх заавар биш.","labActivityId":"g10-sulfur-acid"}]},{"id":"4.1","chapterId":"4","title":"Шатамхай түлшний эх үүсвэр. Байгалийн хий","bookPages":"102–107","objectives":[{"id":"g10-4.1-o1","text":"Метаны бүрэн шаталтыг тэнцүүл."},{"id":"g10-4.1-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Бүрэн шаталт"],"notes":[{"id":"g10-4.1-n1","title":"Шатамхай түлшний эх үүсвэр. Байгалийн хий","blocks":[{"t":"key","term":"Бүрэн шаталт","x":"Хүчилтөрөгч хангалттай үед нүүрсустөрөгчөөс CO₂ ба ус үүсэх исэлдэлт."},{"t":"p","x":"Байгалийн хийн гол бүрэлдэхүүн метан. Нүүрсустөрөгчийн бүрэн шаталтад нүүрстөрөгч CO₂, устөрөгч H₂O болно. Хүчилтөрөгч хүрэлцэхгүй бол CO ба тортог үүсэж болно."},{"t":"p","x":"Түлшийг зөвхөн нэг граммын илчлэгээр сонгохгүй. Нийт ялгаралт, тээвэрлэлт, нөөц ба ашиглалтын үр ашгийг харьцуулна."},{"t":"ex","q":"Метаны бүрэн шаталтыг тэнцүүл.","a":"CH₄ + 2O₂ → CO₂ + 2H₂O."}]},{"id":"g10-4.1-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Өнгөгүй CO-ийг дөлний өнгөөр илрүүлэхгүй. Тооцооны загвар нь бодит өрөөний агаарын чанарын хэмжилт биш."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Метаны бүрэн шаталтын бүтээгдэхүүн аль вэ?","a":"CO₂ ба H₂O — Байгалийн хийн гол бүрэлдэхүүн метан. Нүүрсустөрөгчийн бүрэн шаталтад нүүрстөрөгч CO₂, устөрөгч H₂O болно. Хүчилтөрөгч хүрэлцэхгүй бол CO ба тортог үүсэж болно."}]}],"flashcards":[{"id":"g10-4.1-c1","front":"Бүрэн шаталт гэж юу вэ?","back":"Хүчилтөрөгч хангалттай үед нүүрсустөрөгчөөс CO₂ ба ус үүсэх исэлдэлт."},{"id":"g10-4.1-c2","front":"Метаны бүрэн шаталтыг тэнцүүл.","back":"CH₄ + 2O₂ → CO₂ + 2H₂O."},{"id":"g10-4.1-c3","front":"Метаны бүрэн шаталтын бүтээгдэхүүн аль вэ?","back":"CO₂ ба H₂O"},{"id":"g10-4.1-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Өнгөгүй CO-ийг дөлний өнгөөр илрүүлэхгүй. Тооцооны загвар нь бодит өрөөний агаарын чанарын хэмжилт биш."}],"quiz":[{"id":"g10-4.1-q1","question":"Метаны бүрэн шаталтын бүтээгдэхүүн аль вэ?","options":["CO ба H₂","CO₂ ба H₂O","C ба H₂","CH₃OH"],"answer":1,"explanation":"Байгалийн хийн гол бүрэлдэхүүн метан. Нүүрсустөрөгчийн бүрэн шаталтад нүүрстөрөгч CO₂, устөрөгч H₂O болно. Хүчилтөрөгч хүрэлцэхгүй бол CO ба тортог үүсэж болно. Түлшийг зөвхөн нэг граммын илчлэгээр сонгохгүй. Нийт ялгаралт, тээвэрлэлт, нөөц ба ашиглалтын үр ашгийг харьцуулна."},{"id":"g10-4.1-q2","question":"Метаны 1 моль бүрэн шатахад хэдэн моль O₂ хэрэгтэй вэ?","options":["0.5","1","2","4"],"answer":2,"explanation":"CH₄ + 2O₂ → CO₂ + 2H₂O."}],"questions":[{"id":"g10-4.1-s1","level":"medium","stem":"Метаны бүрэн шаталтыг тэнцүүл.","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["CH₄ + 2O₂ → CO₂ + 2H₂O.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"CH₄ + 2O₂ → CO₂ + 2H₂O."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Өнгөгүй CO-ийг дөлний өнгөөр илрүүлэхгүй. Тооцооны загвар нь бодит өрөөний агаарын чанарын хэмжилт биш."],"model":"Өнгөгүй CO-ийг дөлний өнгөөр илрүүлэхгүй. Тооцооны загвар нь бодит өрөөний агаарын чанарын хэмжилт биш."}]}],"practicals":[{"id":"g10-combustion-prac","title":"Метаны бүрэн ба дутуу шаталт","ref":"Хими X · х.103–106","aim":"Метаны бүрэн ба дутуу шаталт — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т метан, ②-т O₂-ийн хэмжсэн хэсэг дамжуулж ажиллуул.","Асаагуураар түлш асаан хий, усны уур ба тортгийг ажигла.","O₂/CH₄ харьцааг өөрчилж бүрэн ба дутуу шаталтын бүтээгдэхүүнийг харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. CH₄ + 2O₂ → CO₂ + 2H₂O. Хүчилтөрөгч дутагдвал бодит бүтээгдэхүүний харьцаа орчноос хамаарна.","labActivityId":"g10-combustion"}]},{"id":"4.2","chapterId":"4","title":"Газрын тос. Нүүрс","bookPages":"108–114","objectives":[{"id":"g10-4.2-o1","text":"C₁₀H₂₂ → C₈H₁₈ + ? урвалын дутуу бүтээгдэхүүнийг ол."},{"id":"g10-4.2-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Фракц"],"notes":[{"id":"g10-4.2-n1","title":"Газрын тос. Нүүрс","blocks":[{"t":"key","term":"Фракц","x":"Төстэй буцлах мужтай, хэд хэдэн нүүрсустөрөгч агуулсан хэсэг."},{"t":"p","x":"Газрын тос нь холимог. Фракцлан нэрэхэд ууршилт ба конденсацаар ялгана; баганын доод хэсэг халуун, дээд хэсэг сэрүүн."},{"t":"p","x":"Урт хэлхээтэй бүрэлдэхүүний буцлах муж ба зууралдлага ерөнхийдөө их. Крекинг нь урт молекулыг жижиг алкан, алкен болгон химийн хувиргана."},{"t":"ex","q":"C₁₀H₂₂ → C₈H₁₈ + ? урвалын дутуу бүтээгдэхүүнийг ол.","a":"C₂H₄. Нүүрстөрөгч ба устөрөгчийн атомын тоо хадгалагдана."}]},{"id":"g10-4.2-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Фракц цэвэр нэг бодис биш. Бөмбөлөг унах туршилтад температур, бөмбөлгийн хэмжээ, унах зайг ижил байлгана."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Фракцлан нэрэхэд юу голлон ашигладаг вэ?","a":"Буцлах мужийн ялгаа — Газрын тос нь холимог. Фракцлан нэрэхэд ууршилт ба конденсацаар ялгана; баганын доод хэсэг халуун, дээд хэсэг сэрүүн."}]}],"flashcards":[{"id":"g10-4.2-c1","front":"Фракц гэж юу вэ?","back":"Төстэй буцлах мужтай, хэд хэдэн нүүрсустөрөгч агуулсан хэсэг."},{"id":"g10-4.2-c2","front":"C₁₀H₂₂ → C₈H₁₈ + ? урвалын дутуу бүтээгдэхүүнийг ол.","back":"C₂H₄. Нүүрстөрөгч ба устөрөгчийн атомын тоо хадгалагдана."},{"id":"g10-4.2-c3","front":"Фракцлан нэрэхэд юу голлон ашигладаг вэ?","back":"Буцлах мужийн ялгаа"},{"id":"g10-4.2-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Фракц цэвэр нэг бодис биш. Бөмбөлөг унах туршилтад температур, бөмбөлгийн хэмжээ, унах зайг ижил байлгана."}],"quiz":[{"id":"g10-4.2-q1","question":"Фракцлан нэрэхэд юу голлон ашигладаг вэ?","options":["Буцлах мужийн ялгаа","Протоны тооны ялгаа","Массын тоо","Шаталтын хурд"],"answer":0,"explanation":"Газрын тос нь холимог. Фракцлан нэрэхэд ууршилт ба конденсацаар ялгана; баганын доод хэсэг халуун, дээд хэсэг сэрүүн. Урт хэлхээтэй бүрэлдэхүүний буцлах муж ба зууралдлага ерөнхийдөө их. Крекинг нь урт молекулыг жижиг алкан, алкен болгон химийн хувиргана."},{"id":"g10-4.2-q2","question":"Фракцлан нэрэх ба крекингийн гол ялгаа аль вэ?","options":["Хоёул шинэ молекул үүсгэнэ","Нэрэх физик ялгалт, крекинг химийн хувирал","Хоёул зөвхөн шүүх","Крекинг зөвхөн хөргөнө"],"answer":1,"explanation":"Нэрэхэд молекулын холбоос хэвээр; крекинг урт молекулыг жижиг болгон хувиргана."}],"questions":[{"id":"g10-4.2-s1","level":"medium","stem":"C₁₀H₂₂ → C₈H₁₈ + ? урвалын дутуу бүтээгдэхүүнийг ол.","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["C₂H₄. Нүүрстөрөгч ба устөрөгчийн атомын тоо хадгалагдана.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"C₂H₄. Нүүрстөрөгч ба устөрөгчийн атомын тоо хадгалагдана."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Фракц цэвэр нэг бодис биш. Бөмбөлөг унах туршилтад температур, бөмбөлгийн хэмжээ, унах зайг ижил байлгана."],"model":"Фракц цэвэр нэг бодис биш. Бөмбөлөг унах туршилтад температур, бөмбөлгийн хэмжээ, унах зайг ижил байлгана."}]}],"practicals":[{"id":"g10-oil-distillation-prac","title":"Газрын тосны фракцлах багана","ref":"Хими X · х.109–111","aim":"Газрын тосны фракцлах багана — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["① колбонд газрын тосны сургалтын холимог хий.","Термостатыг 320°C болгож халаалт ба багажийг ажиллуул.","②–⑤ хүлээн авагчийн фракцын эзлэхүүн, температур ба эх колбоны үлдэгдлийг хэмж."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Хий, бензин, керосин, дизель, тосон фракцын зааг нь хялбаршуулсан; бодит нэрэх муруй биш.","labActivityId":"g10-oil-distillation"},{"id":"g10-viscosity-prac","title":"Фракцын зууралдлага: бөмбөлгийн уналт","ref":"Хими X · х.111","aim":"Фракцын зууралдлага: бөмбөлгийн уналт — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["① цилиндрт шинжлэх шингэн, дараа нь ижил хэмжээтэй шилэн бөмбөлөг хий.","Бөмбөлгийг суллаж 10 см унах хугацааг хэмж.","Өөр шингэн эсвэл температуртай давтаж Re ба Стоксын нөхцөлийг шалга."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Сургалтын нягт: бөмбөлөг 2500, шингэн 900 кг/м³. Re≥1 үед Стоксын загварыг найдвартай гэж үзэхгүй.","labActivityId":"g10-viscosity"},{"id":"g10-cracking-prac","title":"Урт хэлхээний крекинг","ref":"Хими X · х.112–114","aim":"Урт хэлхээний крекинг — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т декан ба Al₂O₃ катализатор, ③-т бромын ус хий.","550°C термостат, халаалт ба багажийг асаа.","②-т үүсэх этен, ①-ийн октан ба бромын өнгө арилалтыг хэмж."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. C₁₀H₂₂ → C₈H₁₈ + C₂H₄ нь нэг боломжит зам; бодит олон бүтээгдэхүүний тархалтыг тооцоогүй.","labActivityId":"g10-cracking"}]},{"id":"4.3","chapterId":"4","title":"Нүүрсустөрөгч","bookPages":"115–122","objectives":[{"id":"g10-4.3-o1","text":"Этен ба бромын урвалыг бич."},{"id":"g10-4.3-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Изомер"],"notes":[{"id":"g10-4.3-n1","title":"Нүүрсустөрөгч","blocks":[{"t":"key","term":"Изомер","x":"Молекул томьёо ижил боловч байгуулалт ялгаатай нэгдлүүд."},{"t":"p","x":"Алканы нээлттэй ханасан хэлхээний ерөнхий томьёо CₙH₂ₙ₊₂. Нэг хоёрлосон холбоотой нээлттэй алкенийх CₙH₂ₙ. Хоёрлосон холбоонд нэгдэх урвал явагдана."},{"t":"p","x":"Этен бромтой нэгдэж 1,2-дибромэтан үүсгэнэ. Бромын усны өнгө арилалт ханаагүй холбооны нотолгоо боловч бусад урвал өнгө арилгаж болохыг анхаар."},{"t":"ex","q":"Этен ба бромын урвалыг бич.","a":"CH₂=CH₂ + Br₂ → CH₂Br–CH₂Br."}]},{"id":"g10-4.3-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Гексаны байгууллын таван изомер бий. Зургийг эргүүлэхэд ижил холбоос хэвээр байвал шинэ изомер болохгүй."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Нээлттэй хэлхээт алкан аль вэ?","a":"C₂H₆ — Алканы нээлттэй ханасан хэлхээний ерөнхий томьёо CₙH₂ₙ₊₂. Нэг хоёрлосон холбоотой нээлттэй алкенийх CₙH₂ₙ. Хоёрлосон холбоонд нэгдэх урвал явагдана."}]}],"flashcards":[{"id":"g10-4.3-c1","front":"Изомер гэж юу вэ?","back":"Молекул томьёо ижил боловч байгуулалт ялгаатай нэгдлүүд."},{"id":"g10-4.3-c2","front":"Этен ба бромын урвалыг бич.","back":"CH₂=CH₂ + Br₂ → CH₂Br–CH₂Br."},{"id":"g10-4.3-c3","front":"Нээлттэй хэлхээт алкан аль вэ?","back":"C₂H₆"},{"id":"g10-4.3-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Гексаны байгууллын таван изомер бий. Зургийг эргүүлэхэд ижил холбоос хэвээр байвал шинэ изомер болохгүй."}],"quiz":[{"id":"g10-4.3-q1","question":"Нээлттэй хэлхээт алкан аль вэ?","options":["C₂H₄","C₃H₆","C₂H₆","C₂H₂"],"answer":2,"explanation":"Алканы нээлттэй ханасан хэлхээний ерөнхий томьёо CₙH₂ₙ₊₂. Нэг хоёрлосон холбоотой нээлттэй алкенийх CₙH₂ₙ. Хоёрлосон холбоонд нэгдэх урвал явагдана. Этен бромтой нэгдэж 1,2-дибромэтан үүсгэнэ. Бромын усны өнгө арилалт ханаагүй холбооны нотолгоо боловч бусад урвал өнгө арилгаж болохыг анхаар."},{"id":"g10-4.3-q2","question":"C₆H₁₄-ийн байгууллын изомер хэд вэ?","options":["3","4","5","6"],"answer":2,"explanation":"Гексан, 2-метилпентан, 3-метилпентан, 2,2-диметилбутан, 2,3-диметилбутан."}],"questions":[{"id":"g10-4.3-s1","level":"medium","stem":"Этен ба бромын урвалыг бич.","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["CH₂=CH₂ + Br₂ → CH₂Br–CH₂Br.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"CH₂=CH₂ + Br₂ → CH₂Br–CH₂Br."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Гексаны байгууллын таван изомер бий. Зургийг эргүүлэхэд ижил холбоос хэвээр байвал шинэ изомер болохгүй."],"model":"Гексаны байгууллын таван изомер бий. Зургийг эргүүлэхэд ижил холбоос хэвээр байвал шинэ изомер болохгүй."}]}],"practicals":[{"id":"g10-isomers-prac","title":"Гексаны таван изомер","ref":"Хими X · х.117","aim":"Гексаны таван изомер — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т 6 C, ②-т 14 H загварын хэсэг хий.","C зангилаануудыг өөрөө сонгож таван ишээр циклгүй холбож багажийг ажиллуул.","Холбоосыг салгаж өөр байгуулалт бүтээн изомерийн нэр ба лавлах буцлах цэгийг харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Бүгд C₆H₁₄. Салаалалт ихсэхэд буцлах цэг ерөнхийдөө буурна; цэвэр бодисын лавлах утга ашиглав.","labActivityId":"g10-isomers"},{"id":"g10-alkene-prac","title":"Бромын ус: алкан ба алкен","ref":"Хими X · х.120","aim":"Бромын ус: алкан ба алкен — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т бромын ус, ②-т хэмжсэн этен дамжуул.","Ажиллуулах/холих товч дарж этен ба Br₂ зарцуулалт, дибромэтан үүсэхийг ажигла.","Шинэ дээжид гексан эсвэл KMnO₄-ийн сорилыг тусад нь харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. C₂H₄ + Br₂ → C₂H₄Br₂. Бром илүүдэхэд өнгө бүрэн арилахгүй; загвар зөвхөн энэхүү нэгдэх замыг тооцно.","labActivityId":"g10-alkene"},{"id":"g10-ethene-preparation-prac","title":"Этанолоос этен гаргах","ref":"Хими X · х.121","aim":"Этанолоос этен гаргах — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т этанол, концентрацтай H₂SO₄-ийн хэмжсэн хэсэг, ③-т бромын ус бэлтгэ.","Термостатыг 180°C болгож халаалт ба багажийг ажиллуул.","②-т үүссэн этен ба ③ бромын өнгө арилалтыг тэмдэглэ."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. C₂H₅OH → C₂H₄ + H₂O. Хүчтэй хүчил, өндөр температур шаарддаг тул зөвхөн виртуал загвар.","labActivityId":"g10-ethene-preparation"}]},{"id":"4.4","chapterId":"4","title":"Спирт. Биотүлш","bookPages":"123–129","objectives":[{"id":"g10-4.4-o1","text":"0.10 моль глюкозын онолын этанолын гарц хэд вэ?"},{"id":"g10-4.4-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Ферментац"],"notes":[{"id":"g10-4.4-n1","title":"Спирт. Биотүлш","blocks":[{"t":"key","term":"Ферментац","x":"Энзимийн тусламжтайгаар сахарыг этанол ба CO₂ болгон хувиргах процесс."},{"t":"p","x":"Спиртийн функциональ бүлэг –OH. Этанол усанд уусаж, шатаж, исэлдэн этаны хүчил өгнө. Функциональ бүлэг нь нэгдлийн гол урвалын шинжийг тодорхойлно."},{"t":"p","x":"Глюкозын ферментацын нийлбэр урвал C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂. Температур ба орчин энзимийн идэвхэд нөлөөлнө; хүчтэй халаалт ферментацыг зогсоож болно."},{"t":"ex","q":"0.10 моль глюкозын онолын этанолын гарц хэд вэ?","a":"1:2 харьцаагаар 0.20 моль буюу 9.214 г этанол. Бодит гарц бага байж болно."}]},{"id":"g10-4.4-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Дихроматын улбар шар өнгө ногоон болох нь исэлдэлтийн сорил. Этанолыг амсах, үнэрлэх сорил хэрэглэхгүй; сорил бодит ундааны аюулгүй байдлыг тогтоохгүй."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Спиртийн функциональ бүлэг аль вэ?","a":"–OH — Спиртийн функциональ бүлэг –OH. Этанол усанд уусаж, шатаж, исэлдэн этаны хүчил өгнө. Функциональ бүлэг нь нэгдлийн гол урвалын шинжийг тодорхойлно."}]}],"flashcards":[{"id":"g10-4.4-c1","front":"Ферментац гэж юу вэ?","back":"Энзимийн тусламжтайгаар сахарыг этанол ба CO₂ болгон хувиргах процесс."},{"id":"g10-4.4-c2","front":"0.10 моль глюкозын онолын этанолын гарц хэд вэ?","back":"1:2 харьцаагаар 0.20 моль буюу 9.214 г этанол. Бодит гарц бага байж болно."},{"id":"g10-4.4-c3","front":"Спиртийн функциональ бүлэг аль вэ?","back":"–OH"},{"id":"g10-4.4-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Дихроматын улбар шар өнгө ногоон болох нь исэлдэлтийн сорил. Этанолыг амсах, үнэрлэх сорил хэрэглэхгүй; сорил бодит ундааны аюулгүй байдлыг тогтоохгүй."}],"quiz":[{"id":"g10-4.4-q1","question":"Спиртийн функциональ бүлэг аль вэ?","options":["–COOH","–OH","C=C","–NH₂"],"answer":1,"explanation":"Спиртийн функциональ бүлэг –OH. Этанол усанд уусаж, шатаж, исэлдэн этаны хүчил өгнө. Функциональ бүлэг нь нэгдлийн гол урвалын шинжийг тодорхойлно. Глюкозын ферментацын нийлбэр урвал C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂. Температур ба орчин энзимийн идэвхэд нөлөөлнө; хүчтэй халаалт ферментацыг зогсоож болно."},{"id":"g10-4.4-q2","question":"Глюкозын нэг молиос онолын хэдэн моль этанол үүсэх вэ?","options":["0.5","1","2","6"],"answer":2,"explanation":"C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂."}],"questions":[{"id":"g10-4.4-s1","level":"medium","stem":"0.10 моль глюкозын онолын этанолын гарц хэд вэ?","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["1:2 харьцаагаар 0.20 моль буюу 9.214 г этанол. Бодит гарц бага байж болно.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"1:2 харьцаагаар 0.20 моль буюу 9.214 г этанол. Бодит гарц бага байж болно."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Дихроматын улбар шар өнгө ногоон болох нь исэлдэлтийн сорил. Этанолыг амсах, үнэрлэх сорил хэрэглэхгүй; сорил бодит ундааны аюулгүй байдлыг тогтоохгүй."],"model":"Дихроматын улбар шар өнгө ногоон болох нь исэлдэлтийн сорил. Этанолыг амсах, үнэрлэх сорил хэрэглэхгүй; сорил бодит ундааны аюулгүй байдлыг тогтоохгүй."}]}],"practicals":[{"id":"g10-ethanol-oxidation-prac","title":"Этанолын исэлдэлтийн өнгөний сорил","ref":"Хими X · х.125","aim":"Этанолын исэлдэлтийн өнгөний сорил — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т этанол, ②-т хүчиллэг дихромат бэлтгэ.","Термостатыг 70°C болгож халаалт, ажиллуулах/холих үйлдлийг эхлүүл.","Улбар шар Cr(VI)-ийн зарцуулалт, ногоон Cr(III) ба этаны хүчил үүсэхийг харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. 3C₂H₅OH + 2Cr₂O₇²⁻ + 16H⁺ → 3CH₃COOH + 4Cr³⁺ + 11H₂O. H⁺ илүүдэлтэй идеал загвар.","labActivityId":"g10-ethanol-oxidation"},{"id":"g10-fermentation-prac","title":"Глюкозын ферментац","ref":"Хими X · х.128","aim":"Глюкозын ферментац — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т глюкоз, исгэгч ба ус, ③-т шохойн ус бэлтгэ.","30°C термостат, усан хаалтыг тохируулж ажиллуул.","Цагийг хурдасгаж этанол, CO₂ ба сахарын үлдэгдлийг хэмж; өндөр температурт исгэгч идэвхгүйжих хяналт хий."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂. Кинетик нь жишээ; бодит омог, тэжээллэг орчин ба гарцыг төлөөлөхгүй.","labActivityId":"g10-fermentation"}]},{"id":"4.5","chapterId":"4","title":"Карбон хүчил","bookPages":"130–135","objectives":[{"id":"g10-4.5-o1","text":"Этаны хүчил ба этанолын урвалыг бич."},{"id":"g10-4.5-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Эстержих"],"notes":[{"id":"g10-4.5-n1","title":"Карбон хүчил","blocks":[{"t":"key","term":"Эстержих","x":"Карбон хүчил ба спиртээс эстер, ус үүсэх эргэх урвал."},{"t":"p","x":"Карбон хүчлийн функциональ бүлэг –COOH. Этаны хүчил сул хүчил тул усанд хэсэгчлэн ионжино. Сул гэдэг нь заавал шингэрүүлсэн гэсэн үг биш."},{"t":"p","x":"Этаны хүчил карбонаттай CO₂, металлаар H₂, суурьтай давс ба ус өгнө. Этанолтой хүчиллэг катализаторын орчинд этил этаноат үүсгэнэ."},{"t":"ex","q":"Этаны хүчил ба этанолын урвалыг бич.","a":"CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O."}]},{"id":"g10-4.5-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"1 М этаны хүчилд pH≈2.4 гэж тэнцвэрээр тооцно; сурах бичгийн pH≈5 жишээг тооцооны лавлах утга болгон хуулбарлахгүй. Ижил моль хүчлийн эцсийн CO₂ гарц хангалттай хугацаанд адил байж болно."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Ижил концентрацтай HCl ба CH₃COOH-ийн аль нь бага pH-тай вэ?","a":"HCl — Карбон хүчлийн функциональ бүлэг –COOH. Этаны хүчил сул хүчил тул усанд хэсэгчлэн ионжино. Сул гэдэг нь заавал шингэрүүлсэн гэсэн үг биш."}]}],"flashcards":[{"id":"g10-4.5-c1","front":"Эстержих гэж юу вэ?","back":"Карбон хүчил ба спиртээс эстер, ус үүсэх эргэх урвал."},{"id":"g10-4.5-c2","front":"Этаны хүчил ба этанолын урвалыг бич.","back":"CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O."},{"id":"g10-4.5-c3","front":"Ижил концентрацтай HCl ба CH₃COOH-ийн аль нь бага pH-тай вэ?","back":"HCl"},{"id":"g10-4.5-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"1 М этаны хүчилд pH≈2.4 гэж тэнцвэрээр тооцно; сурах бичгийн pH≈5 жишээг тооцооны лавлах утга болгон хуулбарлахгүй. Ижил моль хүчлийн эцсийн CO₂ гарц хангалттай хугацаанд адил байж болно."}],"quiz":[{"id":"g10-4.5-q1","question":"Ижил концентрацтай HCl ба CH₃COOH-ийн аль нь бага pH-тай вэ?","options":["HCl","CH₃COOH","Заавал ижил","Зөвхөн эзлэхүүнээс хамаарна"],"answer":0,"explanation":"Карбон хүчлийн функциональ бүлэг –COOH. Этаны хүчил сул хүчил тул усанд хэсэгчлэн ионжино. Сул гэдэг нь заавал шингэрүүлсэн гэсэн үг биш. Этаны хүчил карбонаттай CO₂, металлаар H₂, суурьтай давс ба ус өгнө. Этанолтой хүчиллэг катализаторын орчинд этил этаноат үүсгэнэ."},{"id":"g10-4.5-q2","question":"Ижил моль хүчил ба илүүдэл гидрокарбонаттай үед сул хүчил юу өөрчилж болох вэ?","options":["Заавал бага эцсийн CO₂","Эхний урвалын хурд","Нүүрстөрөгчийн атомын масс","CO₂-ийн томьёо"],"answer":1,"explanation":"Удаан хурд нь бага эцсийн гарц гэсэн үг биш. Хангалттай хугацаанд ижил стехиометрийн хэмжээнд хүрч болно."}],"questions":[{"id":"g10-4.5-s1","level":"medium","stem":"Этаны хүчил ба этанолын урвалыг бич.","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["1 М этаны хүчилд pH≈2.4 гэж тэнцвэрээр тооцно; сурах бичгийн pH≈5 жишээг тооцооны лавлах утга болгон хуулбарлахгүй. Ижил моль хүчлийн эцсийн CO₂ гарц хангалттай хугацаанд адил байж болно."],"model":"1 М этаны хүчилд pH≈2.4 гэж тэнцвэрээр тооцно; сурах бичгийн pH≈5 жишээг тооцооны лавлах утга болгон хуулбарлахгүй. Ижил моль хүчлийн эцсийн CO₂ гарц хангалттай хугацаанд адил байж болно."}]}],"practicals":[{"id":"g10-acid-ph-prac","title":"Хүчтэй ба сул хүчлийн pH","ref":"Хими X · х.133","aim":"Хүчтэй ба сул хүчлийн pH — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Ижил концентрацын нөхцөлийг шалгаж HCl, этаны хүчлийг тусад нь ав.","Индикатор нэмж эсвэл pH-ийг хэмжиж харьцуул.","Шингэрүүлсэн хоёр дахь нөхцөлд давтаж хүчил хүчтэй эсэх ба концентрацыг ялга."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"Ижил концентрацад этаны хүчлийн pH өндөр. pKa≈4.76; 1 М дээжийн pH≈2.4, номын ≈5 утгыг лавлах болгон хэрэглэхгүй.","labActivityId":"g10-acid-ph"},{"id":"g10-acid-carbonate-prac","title":"HCl ба этаны хүчил–гидрокарбонат","ref":"Хими X · х.133","aim":"HCl ба этаны хүчил–гидрокарбонат — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Шинэ угсралт бүрд ижил моль NaHCO₃ ав.","Ижил концентраци, эзлэхүүнтэй хоёр хүчлийг тус тус турш.","Эхний хурд ба хангалттай удаан хугацааны нийт CO₂-ийг ялгаж харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Бодисыг амсаж, шууд үнэрлэхгүй. Бодит туршилтыг багшийн хяналттай гүйцэтгэнэ.","result":"CH₃COOH + NaHCO₃ → CH₃COONa + CO₂ + H₂O. Сул хүчил удаан боловч ижил моль хүчлийн нийт гарц заавал бага биш.","labActivityId":"g10-acid-carbonate"},{"id":"g10-esterification-prac","title":"Этил этаноатын эргэх үүсэлт","ref":"Хими X · х.134","aim":"Этил этаноатын эргэх үүсэлт — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т этанол ба мөсөн цууны хүчил, ②-т бага H₂SO₄ катализатор нэм.","75°C термостат ба халаалт асааж ажиллуулж холь.","Этил этаноатын хэмжээ ба үлдэгдлийг хэмж; ус нэмсэн шинэ нөхцөлтэй харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O. K=4 гэсэн идеал жишээ; катализатор тэнцвэрийн хэмжээг өөрчлөхгүй.","labActivityId":"g10-esterification"}]},{"id":"4.6","chapterId":"4","title":"Макромолекулт нэгдэл","bookPages":"136–144","objectives":[{"id":"g10-4.6-o1","text":"Нэгдэх ба конденсацийн полимержилтийг ялга."},{"id":"g10-4.6-o2","text":"Хяналттай харьцуулалт төлөвлөж, нотолгоо ба тайлбарыг ялгах."}],"keyTerms":["Полимер"],"notes":[{"id":"g10-4.6-n1","title":"Макромолекулт нэгдэл","blocks":[{"t":"key","term":"Полимер","x":"Олон мономерийн нэгж холбогдсон өндөр молекулт нэгдэл."},{"t":"p","x":"Этен нэгдэх полимержилтээр полиэтен үүсгэнэ. Конденсацийн полимержилтэд хоёр функциональ бүлэгтэй мономерууд холбогдож жижиг молекул ялгаруулна."},{"t":"p","x":"Найлон нь полиамид; хэрэглэсэн мономероос хамааран давтагдах нэгж өөр. Цардуулын гидролизид том молекул задарч, иодын хөх-хар сорил аажмаар суларна."},{"t":"ex","q":"Нэгдэх ба конденсацийн полимержилтийг ялга.","a":"Нэгдэхэд ханаагүй мономерууд жижиг молекул алдалгүй холбогдоно. Конденсацид ус эсвэл HCl зэрэг жижиг молекул ялгарна."}]},{"id":"g10-4.6-n2","title":"Нотолгоо ба түгээмэл алдаа","blocks":[{"t":"p","x":"Иодын өнгө арилалт нь дангаараа глюкоз үүссэнийг батлахгүй. Хяналт, хугацаа, pH ба температурын нөхцөлийг зэрэг тэмдэглэ."},{"t":"tip","x":"Өөрчлөх, хэмжих, тогтмол байлгах хувьсагчаа ялгаж бич. Хоёр ба түүнээс олон оролдлогыг харьцуул."},{"t":"ex","q":"Цардуул байгаа үед иодын сорил ямар өнгөтэй вэ?","a":"Хөх-хар — Этен нэгдэх полимержилтээр полиэтен үүсгэнэ. Конденсацийн полимержилтэд хоёр функциональ бүлэгтэй мономерууд холбогдож жижиг молекул ялгаруулна."}]}],"flashcards":[{"id":"g10-4.6-c1","front":"Полимер гэж юу вэ?","back":"Олон мономерийн нэгж холбогдсон өндөр молекулт нэгдэл."},{"id":"g10-4.6-c2","front":"Нэгдэх ба конденсацийн полимержилтийг ялга.","back":"Нэгдэхэд ханаагүй мономерууд жижиг молекул алдалгүй холбогдоно. Конденсацид ус эсвэл HCl зэрэг жижиг молекул ялгарна."},{"id":"g10-4.6-c3","front":"Цардуул байгаа үед иодын сорил ямар өнгөтэй вэ?","back":"Хөх-хар"},{"id":"g10-4.6-c4","front":"Энэ сэдэвт юуг андуурч болох вэ?","back":"Иодын өнгө арилалт нь дангаараа глюкоз үүссэнийг батлахгүй. Хяналт, хугацаа, pH ба температурын нөхцөлийг зэрэг тэмдэглэ."}],"quiz":[{"id":"g10-4.6-q1","question":"Цардуул байгаа үед иодын сорил ямар өнгөтэй вэ?","options":["Өнгөгүй","Ногоон","Хөх-хар","Улаан"],"answer":2,"explanation":"Этен нэгдэх полимержилтээр полиэтен үүсгэнэ. Конденсацийн полимержилтэд хоёр функциональ бүлэгтэй мономерууд холбогдож жижиг молекул ялгаруулна. Найлон нь полиамид; хэрэглэсэн мономероос хамааран давтагдах нэгж өөр. Цардуулын гидролизид том молекул задарч, иодын хөх-хар сорил аажмаар суларна."},{"id":"g10-4.6-q2","question":"Гексаметилендиамин ба себакоилхлоридаас ямар найлон үүсэх вэ?","options":["Найлон-6","Найлон-6,6","Найлон-6,10","Полиэтен"],"answer":2,"explanation":"Диамин 6, диацилхлорид нийт 10 нүүрстөрөгчтэй тул найлон-6,10 үүснэ."}],"questions":[{"id":"g10-4.6-s1","level":"medium","stem":"Нэгдэх ба конденсацийн полимержилтийг ялга.","totalMarks":3,"parts":[{"label":"а","prompt":"Хариугаа үндэслэл, тэгшитгэл эсвэл тооцоотой бич.","marks":2,"scheme":["Нэгдэхэд ханаагүй мономерууд жижиг молекул алдалгүй холбогдоно. Конденсацид ус эсвэл HCl зэрэг жижиг молекул ялгарна.","Тайлбартаа бодисын харьцаа эсвэл холбогдох шинжийг зөв хэрэглэсэн."],"model":"Нэгдэхэд ханаагүй мономерууд жижиг молекул алдалгүй холбогдоно. Конденсацид ус эсвэл HCl зэрэг жижиг молекул ялгарна."},{"label":"б","prompt":"Үр дүнг хэрэглэх нэг нөхцөл эсвэл хязгаарлалтыг тайлбарла.","marks":1,"scheme":["Иодын өнгө арилалт нь дангаараа глюкоз үүссэнийг батлахгүй. Хяналт, хугацаа, pH ба температурын нөхцөлийг зэрэг тэмдэглэ."],"model":"Иодын өнгө арилалт нь дангаараа глюкоз үүссэнийг батлахгүй. Хяналт, хугацаа, pH ба температурын нөхцөлийг зэрэг тэмдэглэ."}]}],"practicals":[{"id":"g10-nylon-prac","title":"Хоёр фазын зааг дээр найлон-6,10 үүсэх","ref":"Хими X · х.138","aim":"Хоёр фазын зааг дээр найлон-6,10 үүсэх — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["①-т усан диамин, ②-т циклогексан дахь себакоилхлорид бэлтгэ.","Багажийг ажиллуулж хоёр фазын заагт найлон-6,10 үүсэхийг ажигла.","Үүссэн утсыг ороож ④-т ав; массыг болон HCl-ийн хэмжээг өөр молийн харьцаатай харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Найлон-6,10-ийн давтагдах нэгж [–NH–(CH₂)₆–NH–CO–(CH₂)₈–CO–]. Нийт HCl нь зарцуулагдсан функциональ бүлгийн тоотой тэнцэнэ; төгсгөлийн бүлгийг үл хайхрахгүй.","labActivityId":"g10-nylon"},{"id":"g10-starch-prac","title":"Цардуулын гидролизийн есөн нөхцөл","ref":"Хими X · х.142–143","aim":"Цардуулын гидролизийн есөн нөхцөл — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["Есөн үүрэнд ижил цардуул авч хүчил, NaOH, амилаза гэсэн гурван орчин × гурван температур төлөвлө.","Үүр бүрийн температурыг тусдаа тохируулж ажиллуул; иодын бага дуслаар өнгийг шалга.","Үлдсэн цардуул, мальтоз/глюкоз ба энзимийн идэвхгүйжилтийг ижил хугацаанд харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Иодын хөх-хар өнгө үлдсэн цардуултай холбоотой. NaOH дангаараа богино хугацаанд цардуулыг хурдан гидролизлохгүй; коэффициентүүд нь сургалтын жишээ.","labActivityId":"g10-starch"},{"id":"g10-plastic-audit-prac","title":"Хуванцар хаягдлын массын бүртгэл","ref":"Хими X · х.141","aim":"Хуванцар хаягдлын массын бүртгэл — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","steps":["PET ба PE-ийн дээжийг тавцангууд руу хэмжиж ангил.","Жинг ажиллуулж нийт хаягдал ба ангилсан хэсгийн массыг хэмж.","Дахин ашиглах хэсгийг ③ тавцанд бодитоор шилжүүлж нийт масстай харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","result":"Ширээн дээрх нэмсэн бодис, удирдлага ба хэмжилтээр үр дүн гарна. Массыг тавцангаар хэмжинэ; бодит дахин боловсруулалтын хувь эсвэл байгаль дахь задралын хурд биш.","labActivityId":"g10-plastic-audit"}]}],"glossary":[{"term":"Моль","definition":"6.022×10²³ жижиг хэсэг агуулсан бодисын тоо хэмжээний нэгж.","topicId":"1.1"},{"term":"Хроматограмм","definition":"Холимгийн бүрэлдэхүүний ялгаатай шилжилтийг харуулсан зураг.","topicId":"1.2"},{"term":"Титрлэлт","definition":"Мэдэгдсэн концентрацтай уусмалаар урвалд оруулж үл мэдэгдэх тоо хэмжээг тогтоох арга.","topicId":"1.3"},{"term":"Чанарын сорил","definition":"Ион эсвэл бодисыг онцлог ажиглалтаар ялган таних туршилт.","topicId":"1.4"},{"term":"Урвалын хурд","definition":"Нэгж хугацаанд эх бодис зарцуулагдах эсвэл бүтээгдэхүүн үүсэх хэмжээ.","topicId":"2.1"},{"term":"Динамик тэнцвэр","definition":"Битүү системд шууд ба буцах урвалын хурд тэнцсэн төлөв.","topicId":"2.2"},{"term":"Электролиз","definition":"Гаднын цахилгаан гүйдлээр химийн хувирал явуулах үйл явц.","topicId":"2.3"},{"term":"Хайлш","definition":"Металлын нэг эсвэл хэд хэдэн элементтэй үүсгэсэн холимог.","topicId":"3.1"},{"term":"Шохойн эргэлт","definition":"CaCO₃, CaO, Ca(OH)₂-ийн хоорондын хувирлын холбоо.","topicId":"3.2"},{"term":"Контактын арга","definition":"SO₂-ийг катализатороор SO₃ болгон исэлдүүлж хүхрийн хүчил үйлдвэрлэх арга.","topicId":"3.3"},{"term":"Бүрэн шаталт","definition":"Хүчилтөрөгч хангалттай үед нүүрсустөрөгчөөс CO₂ ба ус үүсэх исэлдэлт.","topicId":"4.1"},{"term":"Фракц","definition":"Төстэй буцлах мужтай, хэд хэдэн нүүрсустөрөгч агуулсан хэсэг.","topicId":"4.2"},{"term":"Изомер","definition":"Молекул томьёо ижил боловч байгуулалт ялгаатай нэгдлүүд.","topicId":"4.3"},{"term":"Ферментац","definition":"Энзимийн тусламжтайгаар сахарыг этанол ба CO₂ болгон хувиргах процесс.","topicId":"4.4"},{"term":"Эстержих","definition":"Карбон хүчил ба спиртээс эстер, ус үүсэх эргэх урвал.","topicId":"4.5"},{"term":"Полимер","definition":"Олон мономерийн нэгж холбогдсон өндөр молекулт нэгдэл.","topicId":"4.6"}],"errata":[{"topicId":"4.5","noteId":"g10-4.5-n2","text":"1 М этаны хүчилд pH≈2.4 гэж тэнцвэрээр тооцно; сурах бичгийн pH≈5 жишээг тооцооны лавлах утга болгон хуулбарлахгүй. Ижил моль хүчлийн эцсийн CO₂ гарц хангалттай хугацаанд адил байж болно."},{"topicId":"2.1","noteId":"g10-2.1-n2","text":"Катализаторын эрэмбэ нь орчин, гадаргуу, концентрацаас хамаарна; номын зөрчилтэй сумыг бүх нөхцөлд хүчинтэй гэж хэрэглэхгүй."}],"elements":[{"z":1,"symbol":"H","name":"Устөрөгч","mass":"1.008","category":"nm","state":"g","period":1,"group":1,"fRow":null,"config":[["1s",1]],"shells":[1],"block":"s","look":"gas","color":"#dbeeff","use":"Пуужингийн түлш, аммиак үйлдвэрлэл"},{"z":2,"symbol":"He","nam