  insert into public.lesson_packs(id,is_published,content) values(incoming.id,true,incoming.content) on conflict(id) do nothing;
  select content into old_pack from public.lesson_packs where id=incoming.id for update;
  for topic in select value from jsonb_array_elements(incoming.content->'topics') loop
   select (ordinality-1)::integer into topic_index from jsonb_array_elements(old_pack->'topics') with ordinality where value->>'id'=topic->>'id';
   if topic_index is null then continue;end if;
   for practical in select value from jsonb_array_elements(topic->'practicals') loop
    select (ordinality-1)::integer into practical_index from jsonb_array_elements(old_pack->'topics'->topic_index->'practicals') with ordinality where value->>'id'=practical->>'id';
    if practical_index is not null then
     old_pack:=jsonb_set(old_pack,array['topics',topic_index::text,'practicals',practical_index::text],(old_pack->'topics'->topic_index->'practicals'->practical_index)||jsonb_build_object('steps',practical->'steps','safety',practical->'safety','result',practical->'result','labActivityId',practical->'labActivityId'));
    end if;
   end loop;
  end loop;
  old_pack:=jsonb_set(old_pack,'{meta}',(old_pack->'meta')||jsonb_build_object('version','2.0.0','note',incoming.content->'meta'->'note'));
  update public.lesson_packs set content=old_pack,updated_at=now() where id=incoming.id;
 end loop;
end $upgrade$;
